fn copy_lookup_extension_constructor_with_paths<TP, MP>(
    ext: &crate::types::decl::ExtensionConstructor,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::ExtensionConstructor
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
{
    crate::types::decl::ExtensionConstructor {
        ext_type_path: type_path(&ext.ext_type_path),
        ext_type_params: ext
            .ext_type_params
            .iter()
            .map(|t| copy_lookup_type_expr_with_paths(ctx, *t, cache, type_path, module_path))
            .collect(),
        ext_args: copy_lookup_constructor_args_with_paths(
            &ext.ext_args,
            ctx,
            cache,
            type_path,
            module_path,
        ),
        ext_ret_type: ext
            .ext_ret_type
            .map(|t| copy_lookup_type_expr_with_paths(ctx, t, cache, type_path, module_path)),
        ext_private: ext.ext_private,
        ext_loc: ext.ext_loc.clone(),
        ext_attributes: ext.ext_attributes.clone(),
        ext_is_exception: ext.ext_is_exception,
    }
}

fn copy_lookup_extension_constructor(
    ext: &crate::types::decl::ExtensionConstructor,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::ExtensionConstructor {
    copy_lookup_extension_constructor_with_paths(
        ext,
        ctx,
        cache,
        &clone_copy_lookup_path,
        &clone_copy_lookup_path,
    )
}

fn copy_lookup_module_type_with_paths<TP, MP>(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::ModuleType
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
{
    match module_type {
        crate::types::decl::ModuleType::MtyIdent(path) => {
            crate::types::decl::ModuleType::MtyIdent(type_path(path))
        }
        crate::types::decl::ModuleType::MtyAlias(alias, path) => {
            crate::types::decl::ModuleType::MtyAlias(*alias, module_path(path))
        }
        crate::types::decl::ModuleType::MtyFunctor {
            param,
            param_type,
            result,
        } => crate::types::decl::ModuleType::MtyFunctor {
            param: param.clone(),
            param_type: param_type.as_ref().map(|inner| {
                Box::new(copy_lookup_module_type_with_paths(
                    inner,
                    ctx,
                    cache,
                    type_path,
                    module_path,
                ))
            }),
            result: Box::new(copy_lookup_module_type_with_paths(
                result,
                ctx,
                cache,
                type_path,
                module_path,
            )),
        },
        crate::types::decl::ModuleType::MtySignature(sig_items) => {
            crate::types::decl::ModuleType::MtySignature(copy_lookup_signature_with_paths(
                sig_items,
                ctx,
                cache,
                type_path,
                module_path,
            ))
        }
    }
}

fn copy_lookup_module_type(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::ModuleType {
    copy_lookup_module_type_with_paths(
        module_type,
        ctx,
        cache,
        &clone_copy_lookup_path,
        &clone_copy_lookup_path,
    )
}

fn copy_lookup_signature_with_paths<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
{
    copy_lookup_signature_with_paths_and_idents(
        sig_items,
        ctx,
        cache,
        type_path,
        module_path,
        None::<std::vec::IntoIter<Option<Ident>>>,
    )
}

fn copy_lookup_signature_with_paths_and_idents<TP, MP, I>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
    type_path: &TP,
    module_path: &MP,
    mut new_idents: Option<I>,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
    I: Iterator<Item = Option<Ident>>,
{
    sig_items
        .iter()
        .map(|item| {
            let new_id = new_idents
                .as_mut()
                .and_then(|idents| idents.next())
                .flatten();
            match item {
                crate::types::decl::SignatureItem::SigValue(id, desc) => {
                    crate::types::decl::SignatureItem::SigValue(
                        new_id.unwrap_or_else(|| id.clone()),
                        copy_lookup_value_description_with_paths(
                            desc,
                            ctx,
                            cache,
                            type_path,
                            module_path,
                        ),
                    )
                }
                crate::types::decl::SignatureItem::SigType(id, decl, rec_status) => {
                    crate::types::decl::SignatureItem::SigType(
                        new_id.unwrap_or_else(|| id.clone()),
                        copy_lookup_type_decl_with_paths(decl, ctx, cache, type_path, module_path),
                        *rec_status,
                    )
                }
                crate::types::decl::SignatureItem::SigTypext(id, ext, ext_status) => {
                    crate::types::decl::SignatureItem::SigTypext(
                        new_id.unwrap_or_else(|| id.clone()),
                        copy_lookup_extension_constructor_with_paths(
                            ext,
                            ctx,
                            cache,
                            type_path,
                            module_path,
                        ),
                        *ext_status,
                    )
                }
                crate::types::decl::SignatureItem::SigModule(id, md, rec_status) => {
                    crate::types::decl::SignatureItem::SigModule(
                        new_id.unwrap_or_else(|| id.clone()),
                        crate::types::decl::ModuleDeclaration {
                            md_type: copy_lookup_module_type_with_paths(
                                &md.md_type,
                                ctx,
                                cache,
                                type_path,
                                module_path,
                            ),
                            md_attributes: md.md_attributes.clone(),
                            md_loc: md.md_loc.clone(),
                            md_path: md.md_path.as_ref().map(type_path),
                        },
                        *rec_status,
                    )
                }
                crate::types::decl::SignatureItem::SigModtype(id, mtd) => {
                    crate::types::decl::SignatureItem::SigModtype(
                        new_id.unwrap_or_else(|| id.clone()),
                        crate::types::decl::ModtypeDeclaration {
                            mtd_type: mtd.mtd_type.as_ref().map(|mty| {
                                copy_lookup_module_type_with_paths(
                                    mty,
                                    ctx,
                                    cache,
                                    type_path,
                                    module_path,
                                )
                            }),
                            mtd_attributes: mtd.mtd_attributes.clone(),
                            mtd_loc: mtd.mtd_loc.clone(),
                        },
                    )
                }
                crate::types::decl::SignatureItem::SigClass => {
                    crate::types::decl::SignatureItem::SigClass
                }
                crate::types::decl::SignatureItem::SigClassType => {
                    crate::types::decl::SignatureItem::SigClassType
                }
            }
        })
        .collect()
}

fn copy_lookup_signature(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    cache: &mut TypeExprRefMap<TypeExprRef>,
) -> crate::types::decl::Signature {
    copy_lookup_signature_with_paths(
        sig_items,
        ctx,
        cache,
        &clone_copy_lookup_path,
        &clone_copy_lookup_path,
    )
}

fn should_rewrite_nested_alias_self_path(
    ctx: &crate::types::context::TypeContext,
    old_name: &str,
    parent_path: &Path,
) -> bool {
    fn same_or_descendant(path: &Path, prefix: &Path) -> bool {
        if path.same(prefix) {
            return true;
        }
        match path {
            Path::Pdot(parent, _, _) => same_or_descendant(parent, prefix),
            Path::Pident(_) | Path::Papply(_, _) => false,
        }
    }

    // OCaml compiler/ml/env.ml:1517 discovers flattened backing units by
    // scraping explicit aliases, then env.ml:1530 prefixes the selected
    // component path. env.ml:1573-1578 stores child components under that
    // selected path. If the resolved name is a registered backing unit for the
    // parent component, or for one of its selected child components, leave it
    // for that alias path; do not infer descendants from flattened spelling.
    let old_path = Path::pident(Ident::create_persistent(old_name));
    let old_name_is_parent_source = ctx
        .alias_sources_for_component_path(parent_path)
        .into_iter()
        .any(|source| source.same(&old_path));
    let old_name_is_registered_component_child = ctx
        .component_paths_for_alias_source(&old_path)
        .into_iter()
        .any(|component_path| same_or_descendant(&component_path, parent_path));
    !(old_name_is_parent_source || old_name_is_registered_component_child)
}

fn rewrite_flattened_alias_child_prefixes<'a>(
    sig: &[crate::types::decl::SignatureItem],
    qualified_alias_path: &Path,
    flattened_access_path: &Path,
    ctx: &'a crate::types::context::TypeContext,
) {
    rewrite_child_module_prefixes_from_sig(
        sig,
        sig,
        qualified_alias_path,
        flattened_access_path,
        None,
        ctx,
    );
}

fn rewrite_flattened_alias_head_prefixes<'a>(
    sig: &mut [crate::types::decl::SignatureItem],
    qualified_alias_path: &Path,
    access_path: &Path,
    pers_env: Option<&crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) {
    let mut source_prefixes = Vec::new();
    let mut add_source_prefix = |source_prefix: Path| {
        if !source_prefix.same(qualified_alias_path)
            && !source_prefixes
                .iter()
                .any(|existing: &Path| existing.same(&source_prefix))
        {
            source_prefixes.push(source_prefix);
        }
    };

    fn append_components(mut path: Path, components: &[&str]) -> Path {
        for component in components {
            path = Path::pdot(path, *component);
        }
        path
    }

    if let Ok((head, components)) = qualified_alias_path.flatten() {
        for split in 1..=components.len() {
            let prefix_components = &components[..split];
            let remaining_components = &components[split..];
            let mut qualified_prefix = Path::pident(head.clone());
            for component in prefix_components {
                qualified_prefix = Path::pdot(qualified_prefix, *component);
            }

            let flat_heads = pers_env
                .map(|pers| pers.flattened_alias_heads_for_path(&qualified_prefix))
                .unwrap_or_default();
            // OCaml compiler/ml/env.ml:1516-1538 discovers alias backing paths by
            // scraping real module declarations, and env.ml:1567-1578 stores the
            // selected child component path in the component table. Do not
            // synthesize flattened names from path spelling here; every source
            // prefix must come from the persistent alias table or the component
            // relation registered while building that table.
            for flat_head in flat_heads {
                add_source_prefix(append_components(
                    Path::pident(Ident::create_persistent(&flat_head)),
                    remaining_components,
                ));
            }
            for alias_source in ctx.alias_sources_for_component_path(&qualified_prefix) {
                let source_prefix = append_components(alias_source, remaining_components);
                add_source_prefix(source_prefix);
            }
        }
    }

    for source_prefix in source_prefixes {
        // OCaml compiler/ml/env.ml:1517 scrapes aliases before
        // env.ml:1530-1538 `prefix_idents`, then compiler/ml/subst.ml:303-309
        // rewrites value descriptions through the selected path. ReScript CMI
        // files can save a nested alias target like `Webapi.Fetch.Response`
        // under the flattened parent prefix `Webapi__Fetch.Response`; rewrite
        // those flattened-prefix-plus-tail paths to the same selected path.
        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
            sig,
            &source_prefix,
            access_path,
            ctx,
        );
        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
            sig,
            &source_prefix,
            access_path,
        );
    }
}

fn rewrite_child_module_prefixes_from_sig<'a>(
    sig_to_rewrite: &[crate::types::decl::SignatureItem],
    source_sig: &[crate::types::decl::SignatureItem],
    old_parent_path: &Path,
    new_parent_path: &Path,
    skip_child_name: Option<&str>,
    ctx: &'a crate::types::context::TypeContext,
) {
    let mut prefixes = Vec::new();
    for item in source_sig {
        if let crate::types::decl::SignatureItem::SigModule(id, _, _) = item {
            if skip_child_name == Some(id.name()) {
                continue;
            }
            let old_prefix = Path::pdot(old_parent_path.clone(), id.name().to_string());
            let new_prefix = Path::pdot(new_parent_path.clone(), id.name().to_string());
            prefixes.push((old_prefix, new_prefix));
        }
    }
    crate::cmi::persistent_env::rewrite_sig_by_path_prefixes(sig_to_rewrite, &prefixes, ctx);
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
) -> crate::types::decl::Signature {
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    copy_lookup_signature(sig_items, ctx, &mut cache)
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst_with_paths<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    type_path: &TP,
    module_path: &MP,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
{
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    copy_lookup_signature_with_paths(sig_items, ctx, &mut cache, type_path, module_path)
}

#[track_caller]
pub(crate) fn copy_lookup_signature_for_subst_with_paths_and_idents<TP, MP>(
    sig_items: &[crate::types::decl::SignatureItem],
    ctx: &TypeContext,
    type_path: &TP,
    module_path: &MP,
    new_idents: Vec<Option<Ident>>,
) -> crate::types::decl::Signature
where
    TP: Fn(&Path) -> Path,
    MP: Fn(&Path) -> Path,
{
    if ctx.compiler_counters_enabled() {
        crate::perf_counters::record_signature_copy(
            std::panic::Location::caller(),
            sig_items.len(),
        );
    }
    let mut cache = TypeExprRefMap::new();
    copy_lookup_signature_with_paths_and_idents(
        sig_items,
        ctx,
        &mut cache,
        type_path,
        module_path,
        Some(new_idents.into_iter()),
    )
}

/// Deep-copy a module type, creating new type expression nodes.
/// Used to avoid in-place modification of shared type expressions
/// when applying path substitutions (matching OCaml's lazy deep-copy
/// behavior in `components_of_module_maker` + `Subst.type_declaration`).
pub(crate) fn copy_lookup_module_type_for_subst(
    module_type: &crate::types::decl::ModuleType,
    ctx: &TypeContext,
) -> crate::types::decl::ModuleType {
    let mut cache = TypeExprRefMap::new();
    copy_lookup_module_type(module_type, ctx, &mut cache)
}

