fn rewrite_alias_pident_child_prefixes<'a>(
    sig: &mut [crate::types::decl::SignatureItem],
    target: &Path,
    access_path: &Path,
    ctx: &'a crate::types::context::TypeContext,
) {
    let child_names = sig
        .iter()
        .filter_map(|item| match item {
            crate::types::decl::SignatureItem::SigModule(id, _, _) => Some(id.name().to_string()),
            _ => None,
        })
        .collect::<Vec<_>>();
    for child_name in child_names {
        let old_prefix = Path::pdot(target.clone(), child_name.clone());
        let new_prefix = Path::pdot(access_path.clone(), child_name);
        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(sig, &old_prefix, &new_prefix, ctx);
        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(sig, &old_prefix, &new_prefix);
    }
}

fn qualify_resolved_signature_for_access_path_inner<'a>(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
    force_generalize_values: bool,
) -> crate::types::decl::Signature {
    let should_rebind_direct_type_family = should_rebind_direct_sig_type_family(mty, access_path);
    let access_path_has_local_root = matches!(path_root_module(access_path), Path::Pident(id) if !id.is_persistent() && id.stamp() != 0);
    let access_path_has_persistent_root =
        matches!(path_root_module(access_path), Path::Pident(id) if id.is_persistent());
    if ctx.compiler_counters_enabled() {
        let kind = if let Some(old_name) = resolved_name {
            match access_path {
                Path::Pident(id) if id.name() == old_name => "resolved_name_exact_pident",
                Path::Pident(_) => "resolved_name_alias_pident",
                Path::Pdot(..) => "resolved_name_pdot",
                Path::Papply(_, _) => "resolved_name_papply",
            }
        } else if matches!(mty, crate::types::decl::ModuleType::MtyAlias(..)) {
            "alias"
        } else if should_rebind_direct_type_family {
            "direct_type_family_rebind"
        } else if access_path_has_persistent_root {
            "persistent_root"
        } else if access_path_has_local_root {
            "local_root"
        } else {
            "other"
        };
        crate::perf_counters::record_signature_qualification(kind, resolved_sig.len());
        crate::perf_counters::record_signature_qualification_name(
            kind,
            access_path.name().as_str(),
            resolved_sig.len(),
        );
    }

    // OCaml compiler/ml/env.ml:1530-1538 always routes component signatures
    // through `prefix_idents` and `Subst.value_description`, even when the
    // current signature contains only values and the substitution is otherwise
    // empty. Do not skip the signature copy based on item shape; the value-type
    // sharing must come from compiler/ml/subst.ml:303-309.
    let mut sig = copy_lookup_signature_for_subst(resolved_sig, ctx);
    let alias_requires_exact_persistent_prefix = matches!(
        (mty, access_path),
        (
            crate::types::decl::ModuleType::MtyAlias(_, target),
            Path::Pident(id),
        ) if id.is_persistent() && !target.same(access_path)
    );
    let mut alias_module_strengthen_path = None;
    if matches!(mty, crate::types::decl::ModuleType::MtyAlias(..)) {
        let strengthen_path = match mty {
            crate::types::decl::ModuleType::MtyAlias(_, target)
                if !alias_requires_exact_persistent_prefix =>
            {
                // OCaml compiler/ml/env.ml:1435-1444 scrapes an alias by
                // strengthening the resolved module type at the alias target
                // path, and compiler/ml/mtype.ml:32-49 leaves value
                // descriptions unchanged. The later env.ml:1529-1538
                // `prefix_idents` pass only substitutes bound identifiers for
                // the selected component path.
                target
            }
            _ => access_path,
        };
        alias_module_strengthen_path = Some(strengthen_path.clone());
        sig = strengthen_sig_for_module_access_path(ctx, strengthen_path, &sig);
    }
    // OCaml compiler/ml/subst.ml:69-84 and subst.ml:87-100 rewrite module
    // and type paths structurally; applicative family paths remain under
    // `Pdot(Papply(...), type_name)`. Do not rebind those paths to the selected
    // access path here. compiler/ml/env.ml:1744-1756 must force
    // `components_of_functor_appl` when that manifest is later expanded.
    if should_rebind_direct_type_family {
        rebind_direct_sig_type_family_to_access_path(ctx, access_path, &mut sig);
    }
    if let Some(old_name) = resolved_name {
        let resolved_alias_to_persistent_root = matches!(
            mty,
            crate::types::decl::ModuleType::MtyAlias(_, Path::Pident(alias_id))
                | crate::types::decl::ModuleType::MtyIdent(Path::Pident(alias_id))
                if alias_id.is_persistent() && alias_id.name() == old_name
        );
        if resolved_alias_to_persistent_root {
            // OCaml compiler/ml/env.ml:1516-1518 scrapes aliases before
            // env.ml:1530-1578 builds component tables. For a persistent-root
            // alias, compiler/ml/mtype.ml:98-102 strengthens child modules into
            // Mty_alias entries at the persistent target, and the current
            // compiler/ml/subst.ml:303-309 value-description substitution only
            // sees this component level. Leave nested module signatures for
            // their own env.ml:1568/1573 lazy component thunks.
            crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                &sig,
                old_name,
                access_path,
                ctx,
            );
            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                &mut sig,
                old_name,
                access_path,
            );
        } else {
            crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                &sig,
                old_name,
                access_path,
                ctx,
            );
            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                &mut sig,
                old_name,
                access_path,
            );
        }
    }
    let alias_access_is_persistent_child = matches!(
        (mty, access_path),
        (
            crate::types::decl::ModuleType::MtyAlias(_, _),
            Path::Pdot(parent, _, _),
        ) if parent.head().is_persistent()
    );
    if let crate::types::decl::ModuleType::MtyAlias(_, target) = mty
        && !target.same(access_path)
        && (!access_path_has_persistent_root || alias_access_is_persistent_child)
    {
        // OCaml compiler/ml/env.ml:1517 scrapes module aliases before
        // compiler/ml/env.ml:1530-1538 prefixes component declarations with the
        // selected access path. Rust persistent signatures are already finalized
        // under their saved unit path, so rewrite that target prefix to the
        // selected alias path before applying the component substitution.
        // This also covers persistent child aliases such as `Web.MediaStream =
        // Web__MediaStream`: env.ml:1008-1013 selects the child component path,
        // then env.ml:1542-1556 exposes value/type descriptions through that
        // selected path rather than the flattened backing unit.
        match target {
            Path::Pident(alias_id) => {
                // OCaml compiler/ml/env.ml:1517 scrapes the persistent alias
                // target, then env.ml:1530 builds the current component
                // substitution with `prefix_idents`. Apply that substitution
                // only at this signature level; nested child component thunks
                // keep their own env.ml:1568/1573 lazy substitution boundary.
                crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                    &sig,
                    alias_id.name(),
                    access_path,
                    ctx,
                );
                crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                    &mut sig,
                    alias_id.name(),
                    access_path,
                );
            }
            Path::Pdot(..) => {
                crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                    &sig,
                    target,
                    access_path,
                    ctx,
                );
                // OCaml compiler/ml/env.ml:1567-1579 keeps child module
                // declarations/components as separate lazy thunks. For an
                // alias such as `module J = Js.Json`, compiler/ml/mtype.ml:98-102
                // strengthens `Kind` to the scraped target `Js.Json.Kind`,
                // while compiler/ml/env.ml:1530 and compiler/ml/subst.ml:87-95
                // expose the selected component path as `J.Kind`. Do not
                // rewrite the child module declaration alias itself here.
                crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix_shallow(
                    &mut sig,
                    target,
                    access_path,
                );
                // OCaml compiler/ml/env.ml:1517 scrapes the alias target and
                // compiler/ml/env.ml:1530-1538 then prefixes the selected
                // component path. If the scraped target came from a flattened
                // runtime unit such as `Js_json`, rewrite that backing unit as
                // well as the source alias path (`Js.Json`) before child
                // components are forced.
                rewrite_flattened_alias_head_prefixes(
                    &mut sig,
                    target,
                    access_path,
                    pers_env.as_ref(),
                    ctx,
                );
            }
            Path::Papply(_, _) => {}
        }
    }
    if let crate::types::decl::ModuleType::MtyAlias(_, target) = mty
        && alias_requires_exact_persistent_prefix
    {
        if !target.same(access_path) {
            match target {
                Path::Pdot(..) => {
                    crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                        &sig,
                        target,
                        access_path,
                        ctx,
                    );
                    // OCaml compiler/ml/env.ml:1567-1579 keeps child module
                    // declarations/components as separate lazy thunks. For an
                    // alias such as `module J = Js.Json`, compiler/ml/mtype.ml:98-102
                    // strengthens `Kind` to the scraped target `Js.Json.Kind`,
                    // while compiler/ml/env.ml:1530 and compiler/ml/subst.ml:87-95
                    // expose the selected component path as `J.Kind`. Do not
                    // rewrite the child module declaration alias itself here.
                    crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix_shallow(
                        &mut sig,
                        target,
                        access_path,
                    );
                    rewrite_flattened_alias_head_prefixes(
                        &mut sig,
                        target,
                        access_path,
                        pers_env.as_ref(),
                        ctx,
                    );
                }
                Path::Pident(alias_id) => {
                    // OCaml compiler/ml/env.ml:1567-1579 stores child
                    // module declarations/components as lazy thunks;
                    // compiler/ml/subst.ml:69-95,303-309,350-377
                    // rewrites only paths reached through the
                    // `prefix_idents` substitution when those thunks
                    // are forced. Keep this alias-target root rewrite
                    // to the current signature level so nested module
                    // value types keep explicit persistent paths until
                    // their own component thunk runs.
                    crate::cmi::persistent_env::rewrite_module_prefix_in_sig_shallow(
                        &sig,
                        alias_id.name(),
                        access_path,
                        ctx,
                    );
                    crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig_shallow(
                        &mut sig,
                        alias_id.name(),
                        access_path,
                    );
                    rewrite_alias_pident_child_prefixes(&mut sig, target, access_path, ctx);
                }
                Path::Papply(_, _) => {}
            }
        }
    }
    if let Some(strengthen_path) = alias_module_strengthen_path.as_ref() {
        strengthen_sig_module_decls_for_module_access_path(&mut sig, strengthen_path);
    }
    crate::cmi::persistent_env::substitute_type_paths_in_sig(&sig, access_path, ctx);
    crate::cmi::persistent_env::substitute_sig_decl_paths_in_place(&mut sig, access_path);
    if force_generalize_values {
        crate::types::ctype::force_generalize_signature_values(ctx, &sig);
    }
    sig
}

pub(crate) fn qualify_resolved_signature_for_access_path<'a>(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> crate::types::decl::Signature {
    qualify_resolved_signature_for_access_path_inner(
        access_path,
        mty,
        resolved_sig,
        resolved_name,
        pers_env,
        ctx,
        true,
    )
}

pub(crate) fn qualify_resolved_signature_for_local_components<'a>(
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    resolved_sig: &crate::types::decl::Signature,
    resolved_name: Option<&str>,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> crate::types::decl::Signature {
    qualify_resolved_signature_for_access_path_inner(
        access_path,
        mty,
        resolved_sig,
        resolved_name,
        pers_env,
        ctx,
        false,
    )
}

pub(crate) fn build_qualified_signature_for_access_path<'a>(
    env: &Env,
    access_path: &Path,
    mty: &crate::types::decl::ModuleType,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<crate::types::decl::Signature> {
    let (sig, resolved_name) = env.resolve_module_type(mty, pers_env, ctx, cache_mode)?;
    Some(qualify_resolved_signature_for_access_path(
        access_path,
        mty,
        &sig,
        resolved_name.as_deref(),
        pers_env,
        ctx,
    ))
}

fn lookup_pident_module_for_path<'a>(
    env: &'a Env,
    module_path: &Path,
    id: &Ident,
) -> Option<&'a crate::types::decl::ModuleDeclaration> {
    // OCaml compiler/ml/env.ml:781-788 path lookup uses `IdTbl.find_same`
    // for `Pident` and falls through to the persistent unit when that exact
    // identity is not present. Name lookup belongs to source Longident lookup
    // (`lookup_module_descr_aux`, compiler/ml/env.ml:1000-1007), so a local or
    // opened `Dom` must not shadow the persistent `Dom` carried by a type path.
    if id.is_persistent() {
        env.lookup_module_ident_exact(id).ok()
    } else {
        env.lookup_module(module_path)
            .or_else(|_| env.find_module(id.name()))
            .ok()
    }
}

fn build_module_signature_for_path<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<(Path, crate::types::decl::Signature)> {
    let resolved = match module_path {
        Path::Pident(id) => {
            if let Some(md) = lookup_pident_module_for_path(env, module_path, id) {
                let access_path = if id.is_persistent() {
                    // OCaml compiler/ml/env.ml:1000-1007 resolves an exact
                    // persistent unit through that unit's `ps_comps` before
                    // any alias recovery. Keep the selected path as the
                    // requested unit (`Belt_Id`) even if an opened declaration
                    // also carries a qualified alias path (`Belt.Id`); the
                    // component substitution at env.ml:1530-1538 then prefixes
                    // values and types with the exact unit.
                    Path::pident(id.clone())
                } else {
                    if env.has_module_ident(id) {
                        Path::pident(id.clone())
                    } else {
                        md.md_path
                            .clone()
                            .unwrap_or_else(|| Path::pident(id.clone()))
                    }
                };
                let sig = build_qualified_signature_for_access_path(
                    env,
                    &access_path,
                    &md.md_type,
                    pers_env,
                    ctx,
                    cache_mode,
                )?;
                Some((access_path, sig))
            } else if let Some(pers) = pers_env.as_mut() {
                if let Some(ps) = pers.find_pers_struct(id.name(), ctx) {
                    let access_path = Path::pident(Ident::create_persistent(id.name()));
                    let mut sig = copy_lookup_signature_for_subst(&ps.ps_sig, ctx);
                    if let Some(qualified_alias_path) =
                        pers.qualified_alias_path_for_flattened_head(id.name())
                    {
                        // OCaml compiler/ml/env.ml:1000-1007 resolves the
                        // exact persistent unit before alias recovery, then
                        // env.ml:1530-1538 prefixes component value/type
                        // descriptions with that selected path via
                        // compiler/ml/subst.ml:303-309. If the loaded ps_sig
                        // was already observed through the qualified alias
                        // (`Belt.Id`), rewrite the whole prefix back to the
                        // exact unit (`Belt_Id`), not only child-module
                        // prefixes.
                        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                            &mut sig,
                            &qualified_alias_path,
                            &access_path,
                        );
                        rewrite_flattened_alias_child_prefixes(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                    }
                    Some((access_path, sig))
                } else {
                    let source_path = Path::pident(id.clone());
                    let qualified_alias_path = pers
                        .qualified_alias_path_for_flattened_head(id.name())
                        .or_else(|| {
                            ctx.component_paths_for_alias_source(&source_path)
                                .into_iter()
                                .find(|qualified_alias_path| {
                                    !qualified_alias_path.same(module_path)
                                })
                        })
                        .filter(|qualified_alias_path| !qualified_alias_path.same(module_path));
                    if let Some(qualified_alias_path) = qualified_alias_path {
                        // OCaml compiler/ml/env.ml:1000-1007 resolves the
                        // exact persistent path first; env.ml:1529-1538 then
                        // runs `prefix_idents` with that exact path, and
                        // compiler/ml/subst.ml:180-181 rewrites package module
                        // type paths through `modtype_path`. If Rust has only
                        // the already-selected flattened alias component table
                        // available here, reuse its contents but restore the
                        // exact unit prefix (`Belt_Id`, not `Belt.Id`).
                        let access_path = Path::pident(id.clone());
                        return with_resolved_module_components_for_path(
                            &qualified_alias_path,
                            env,
                            pers_env,
                            ctx,
                            |components| {
                                let mut sig =
                                    copy_lookup_signature_for_subst(components.signature(), ctx);
                                crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                    &sig,
                                    &qualified_alias_path,
                                    &access_path,
                                    ctx,
                                );
                                crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                    &mut sig,
                                    &qualified_alias_path,
                                    &access_path,
                                );
                                rewrite_flattened_alias_child_prefixes(
                                    &sig,
                                    &qualified_alias_path,
                                    &access_path,
                                    ctx,
                                );
                                (access_path, sig)
                            },
                        );
                    }
                    None
                }
            } else {
                let raw_sig = if id.is_persistent() {
                    ctx.with_raw_module_sig(id.name(), |raw_sig| raw_sig.clone())
                        .or_else(|| {
                            ctx.get_or_load_raw_module_sig(id.name())
                                .map(|sig| sig.as_ref().clone())
                        })
                } else {
                    None
                };
                if let Some(raw_sig) = raw_sig {
                    // OCaml compiler/ml/env.ml:669-678 stores persistent
                    // `ps_comps` from the raw `sign` separately from the lazy
                    // `ps_sig = Subst.signature ...`; env.ml:1000-1007 returns
                    // those components for qualified type lookup before
                    // ctype.ml:1367-1372 falls back to env.ml:903-914
                    // `normalize_path`. Recover the component view from the raw
                    // signature cache without forcing the full-signature copy.
                    let access_path = Path::pident(id.clone());
                    let mut sig = raw_sig;
                    let source_path = Path::pident(id.clone());
                    if let Some(qualified_alias_path) = ctx
                        .component_paths_for_alias_source(&source_path)
                        .into_iter()
                        .next()
                    {
                        crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                        crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                            &mut sig,
                            &qualified_alias_path,
                            &access_path,
                        );
                        rewrite_flattened_alias_child_prefixes(
                            &sig,
                            &qualified_alias_path,
                            &access_path,
                            ctx,
                        );
                    }
                    return Some((access_path, sig));
                }
                let source_path = Path::pident(id.clone());
                let qualified_alias_path = ctx
                    .component_paths_for_alias_source(&source_path)
                    .into_iter()
                    .find(|qualified_alias_path| !qualified_alias_path.same(module_path));
                if let Some(qualified_alias_path) = qualified_alias_path {
                    // OCaml compiler/ml/env.ml:1000-1007 resolves the exact
                    // module first; env.ml:1529-1538 then prefixes component
                    // declarations with that exact path, and
                    // compiler/ml/subst.ml:180-181 applies the same prefix to
                    // package module-type paths. The ctype-only path has no
                    // `PersistentEnv`, so recover from Rust's cached alias
                    // components while keeping OCaml's exact persistent prefix.
                    let access_path = Path::pident(id.clone());
                    return with_resolved_module_components_for_path(
                        &qualified_alias_path,
                        env,
                        pers_env,
                        ctx,
                        |components| {
                            let mut sig =
                                copy_lookup_signature_for_subst(components.signature(), ctx);
                            crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                &sig,
                                &qualified_alias_path,
                                &access_path,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                &mut sig,
                                &qualified_alias_path,
                                &access_path,
                            );
                            rewrite_flattened_alias_child_prefixes(
                                &sig,
                                &qualified_alias_path,
                                &access_path,
                                ctx,
                            );
                            (access_path, sig)
                        },
                    );
                }
                None
            }
        }
        Path::Pdot(parent, submodule_name, _) => {
            let (resolved_parent_path, access_path, md) = lookup_module_in_resolved_path(
                parent,
                submodule_name.as_str(),
                env,
                pers_env,
                ctx,
            )?;
            let (sig, resolved_name) =
                env.resolve_module_type(&md.md_type, pers_env, ctx, cache_mode)?;
            let mut sig = copy_lookup_signature_for_subst(&sig, ctx);
            if matches!(&md.md_type, crate::types::decl::ModuleType::MtyAlias(..)) {
                sig = strengthen_sig_for_module_access_path(ctx, &access_path, &sig);
            }
            let mut should_rebind_direct_type_family =
                should_rebind_direct_sig_type_family(&md.md_type, &access_path);
            if module_type_has_hidden_unpack_ident(&md.md_type) {
                should_rebind_direct_type_family = true;
            }
            if should_rebind_direct_type_family {
                rebind_direct_sig_type_family_to_access_path(ctx, &access_path, &mut sig);
            }
            if let Some(ref old_name) = resolved_name {
                if should_rewrite_nested_alias_self_path(ctx, old_name, &resolved_parent_path) {
                    crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                        &sig,
                        old_name,
                        &access_path,
                        ctx,
                    );
                    crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                        &mut sig,
                        old_name,
                        &access_path,
                    );
                }
            }
            if let crate::types::decl::ModuleType::MtyAlias(_, ref target) = md.md_type {
                if !target.same(&access_path) {
                    match target {
                        Path::Pdot(..) => {
                            crate::cmi::persistent_env::rewrite_sig_by_path_prefix(
                                &sig,
                                target,
                                &access_path,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_sig_paths_by_path_prefix(
                                &mut sig,
                                target,
                                &access_path,
                            );
                            rewrite_flattened_alias_head_prefixes(
                                &mut sig,
                                target,
                                &access_path,
                                pers_env.as_ref(),
                                ctx,
                            );
                        }
                        Path::Pident(alias_id) => {
                            crate::cmi::persistent_env::rewrite_module_prefix_in_sig(
                                &sig,
                                alias_id.name(),
                                &access_path,
                                ctx,
                            );
                            crate::cmi::persistent_env::rewrite_module_prefix_paths_in_sig(
                                &mut sig,
                                alias_id.name(),
                                &access_path,
                            );
                            rewrite_alias_pident_child_prefixes(
                                &mut sig,
                                target,
                                &access_path,
                                ctx,
                            );
                        }
                        Path::Papply(_, _) => {}
                    }
                }
            }
            crate::cmi::persistent_env::substitute_type_paths_in_sig(&sig, &access_path, ctx);
            crate::cmi::persistent_env::substitute_sig_decl_paths_in_place(&mut sig, &access_path);
            crate::types::ctype::force_generalize_signature_values(ctx, &sig);
            let flattened_heads = pers_env
                .as_ref()
                .map(|pers| pers.flattened_alias_heads_for_path(&resolved_parent_path))
                .unwrap_or_default();
            if !flattened_heads.is_empty() {
                with_resolved_module_components_for_path(
                    parent,
                    env,
                    pers_env,
                    ctx,
                    |components| {
                        let parent_sig = components.signature();
                        for flat_head in &flattened_heads {
                            let flattened_parent =
                                Path::pident(Ident::create_persistent(flat_head));
                            if !flattened_parent.same(&resolved_parent_path) {
                                rewrite_child_module_prefixes_from_sig(
                                    &sig,
                                    parent_sig,
                                    &resolved_parent_path,
                                    &flattened_parent,
                                    Some(submodule_name.as_str()),
                                    ctx,
                                );
                            }
                        }
                    },
                )?;
            }
            Some((access_path, sig))
        }
        Path::Papply(_, _) => None,
    };

    if resolved.is_some() {
        return resolved;
    }

    if matches!(module_path, Path::Papply(_, _)) {
        return None;
    }

    let head = module_path.head();
    if !head.is_persistent() && head.stamp() != 0 {
        return None;
    }

    if ctx.persistent_env_is_in_process() {
        return None;
    }

    let load_paths = ctx.load_paths();
    if load_paths.is_empty() {
        return None;
    }

    let mut visiting = HashSet::new();
    let sig = crate::types::ctype::resolve_module_signature_through_cmi(
        ctx,
        &load_paths,
        module_path,
        &mut visiting,
    )?;
    crate::types::ctype::force_generalize_signature_values(ctx, &sig);
    Some((module_path.clone(), sig))
}

pub(crate) fn resolve_module_signature_for_path<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<(Path, crate::types::decl::Signature)> {
    resolve_module_signature_for_path_shared(module_path, env, pers_env, ctx)
        .map(|(path, sig)| (path, sig.as_ref().clone()))
}

pub(crate) fn resolve_module_signature_for_path_shared<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<(Path, std::sync::Arc<crate::types::decl::Signature>)> {
    with_resolved_module_components_for_path(module_path, env, pers_env, ctx, |components| {
        (components.access_path().clone(), components.signature_arc())
    })
}

pub(crate) fn alias_target_for_module_path<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path {
        Path::Pident(id) => {
            // OCaml compiler/ml/env.ml:865-875 resolves an exact
            // `Path.Pident` module through `IdTbl.find_same`; env.ml:285-290
            // skips opened component tables. Do not let a same-name opened
            // alias answer alias-target scraping for an already-selected path.
            let md = env.find_module_same(id).ok()?;
            match &md.md_type {
                crate::types::decl::ModuleType::MtyAlias(_, target)
                | crate::types::decl::ModuleType::MtyIdent(target) => Some(target.clone()),
                _ => None,
            }
        }
        Path::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/typecore.ml:776-787 `expand_path` asks
                // compiler/ml/env.ml:800-813 `Env.find_type` before falling
                // back to `Env.normalize_path`. For a dotted type path, that
                // first step descends through env.ml:781-793
                // `find_module_descr` and the component table; it does not
                // force env.ml:1568's `comp_modules` thunk just to inspect a
                // module alias while comparing constructor result paths.
                components
                    .lookup_module(module_name.as_str())
                    .and_then(|(_, _, md)| match &md.md_type {
                        crate::types::decl::ModuleType::MtyAlias(_, target)
                        | crate::types::decl::ModuleType::MtyIdent(target) => Some(target.clone()),
                        _ => None,
                    })
            })?
        }
        Path::Papply(_, _) => None,
    }
}

pub(crate) fn module_alias_target_for_path<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path {
        Path::Pident(id) => {
            // OCaml compiler/ml/env.ml:865-875 resolves an exact
            // `Path.Pident` module through `IdTbl.find_same`; env.ml:285-290
            // skips opened component tables. This keeps persistent runtime roots
            // such as `Dom` from being strengthened through opened aliases before
            // compiler/ml/ctype.ml:1367-1372 normalizes the path.
            let md = env.find_module_same(id).ok()?;
            match &md.md_type {
                crate::types::decl::ModuleType::MtyAlias(_, target) => Some(target.clone()),
                _ => None,
            }
        }
        Path::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/env.ml:781-793 lets
                // `lookup_module_descr` navigate component tables without
                // forcing env.ml:1568's `comp_modules` thunk. This helper is
                // only asking whether the component declaration is an alias so
                // Rust can choose a recovery path; using
                // `lookup_qualified_module` here would force
                // compiler/ml/subst.ml:378-400-style identifier renaming
                // before OCaml's env.ml:865-882 `find_module` path asks for
                // the module declaration itself.
                components
                    .lookup_module(module_name.as_str())
                    .and_then(|(_, _, md)| match &md.md_type {
                        crate::types::decl::ModuleType::MtyAlias(_, target) => Some(target.clone()),
                        _ => None,
                    })
            })?
        }
        Path::Papply(_, _) => None,
    }
}

fn raw_alias_target_for_module_path<'a>(
    module_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<Path> {
    match module_path {
        Path::Pident(_) => alias_target_for_module_path(module_path, env, pers_env, ctx),
        Path::Pdot(parent, module_name, _) => {
            with_resolved_module_components_for_path(parent, env, pers_env, ctx, |components| {
                // OCaml compiler/ml/env.ml:781-793 lets
                // `find_module_descr` descend through component tables, while
                // env.ml:865-882 only forces `comp_modules` for callers that
                // need the module declaration itself. This raw alias probe is
                // used while mirroring compiler/ml/subst.ml:91-95 prefix
                // rewriting of copied type paths, so inspect the component
                // declaration without running compiler/ml/subst.ml:378-400
                // child-signature identifier freshening.
                components
                    .lookup_module(module_name.as_str())
                    .and_then(|(_, _, md)| match &md.md_type {
                        crate::types::decl::ModuleType::MtyAlias(_, target)
                        | crate::types::decl::ModuleType::MtyIdent(target) => Some(target.clone()),
                        _ => None,
                    })
            })?
        }
        Path::Papply(_, _) => None,
    }
}

/// Look up a type declaration for a given path.
/// Tries env first, then the global type stores.
fn lookup_type_decl_for_path<'a>(
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
    lookup_type_decl_for_path_with_cache_mode(
        type_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::FindType,
    )
}

fn lookup_type_decl_for_path_for_probe<'a>(
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
    lookup_type_decl_for_path_with_cache_mode(
        type_path,
        env,
        pers_env,
        ctx,
        ComponentLookupApi::ProbeModuleDescr,
    )
}

fn lookup_type_decl_for_path_with_cache_mode<'a>(
    type_path: &Path,
    env: &Env,
    pers_env: &mut Option<crate::cmi::persistent_env::PersistentEnv>,
    ctx: &'a crate::types::context::TypeContext,
    cache_mode: ComponentLookupApi,
) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
    fn lookup_raw_type_decl_from_module_path<'a>(
        module_path: &Path,
        type_name: &str,
        env: &Env,
        ctx: &'a crate::types::context::TypeContext,
        cache_mode: ComponentLookupApi,
    ) -> Option<Arc<crate::types::decl::TypeDeclaration>> {
        // OCaml compiler/ml/env.ml:1095-1105 and 1138-1143 resolve labels
        // through descriptor component tables; env.ml:800-813 does the same
        // for type lookup. Preserve the caller's descriptor/probe mode here
        // instead of falling back to env.ml:865-882 `find_module`, otherwise a
        // self-manifest fallback can force sibling module declarations while it
        // is only checking raw component type presence.
        let mut no_persistent_env = None;
        with_resolved_module_components_for_path_with_cache_mode(
            module_path,
            env,
            &mut no_persistent_env,
            ctx,
            cache_mode,
            |components| {
                components
                    .lookup_type(type_name)
                    .map(|(_, decl)| Arc::new(decl.clone()))
            },
        )
        .flatten()
    }

    // Only use env.lookup_type directly for simple identifiers. For qualified
    // paths, env.lookup_type currently resolves by leaf name and can return an
    // unrelated declaration with the same type name.
    if let Path::Pident(id) = type_path {
        // OCaml compiler/ml/env.ml:800-813 resolves Pident type paths with
        // `IdTbl.find_same`. Keep this exact here too, so a same-name local
        // alias cannot mask the imported identifier whose stamp is being
        // expanded by ctype.ml:1367-1372.
        if let Ok(decl) = env.find_type_by_ident(id) {
            return Some(Arc::new(decl.clone()));
        }
    }

    // Try stamp-based lookup only for regular type identifiers. Constructor-like
    // paths such as local exception inline-record paths (`C`) share the `Path`
    // representation but are not type bindings, and imported CMI type stamps can
    // collide with local constructor stamps.
    if let Path::Pident(id) = type_path {
        if id.stamp() != 0 {
            if let Ok(decl) = env.find_type_by_ident(id) {
                return Some(Arc::new(decl.clone()));
            }
        }

        // Try stamp-based lookup only for regular type identifiers.
        // Constructor-like paths such as local exception inline-record paths
        // (`C`) share the `Path` representation but are not type bindings, and
        // imported CMI type stamps can collide with local constructor stamps.
        if id.stamp() != 0
            && matches!(
                type_path.constructor_typath(),
                crate::types::path::Typath::Regular(_)
            )
        {
            if let Some(decl) = ctx.find_type_decl_by_stamp(id.stamp()) {
                return Some(Arc::new(decl.clone()));
            }
        }
    }

    // Only use env.lookup_type directly for simple identifiers after exact/stamp
    // lookup. For qualified paths, env.lookup_type currently resolves by leaf
    // name and can return an unrelated declaration with the same type name.
    if let Path::Pident(_) = type_path {
        if let Ok(decl) = env.lookup_type(type_path) {
            return Some(Arc::new(decl.clone()));
        }
    }

    // Try path-based lookup for Pdot paths
    if let Path::Pdot(parent, type_name, _) = type_path {
        let mut deferred_self_manifest_decl: Option<Arc<crate::types::decl::TypeDeclaration>> =
            None;
        let cache_key = path_cache_key(type_path);
        let path_name = type_path.name();

        // Check resolved-sig cache first to avoid re-creating fresh type copies.
        // This approximates OCaml's components_of_module_maker lazy caching.
        // Uses a separate cache from type_decl_by_path to avoid conflicts with
        // expand_head_once entries which have unqualified paths.
        if let Some(cache_key) = cache_key.as_deref() {
            if let Some(decl) = ctx.find_resolved_pdot_type(cache_key) {
                return Some(decl);
            }
        }

        // Inline-record constructor paths are type paths whose parent is also a type path:
        // `<type_path>.<Constructor>`. Rebuild the synthetic record declaration from
        // the parent variant declaration so label disambiguation can recover field types.
        // OCaml compiler/ml/env.ml:822-835 only resolves the parent as a type
        // after `Path.constructor_typath` classifies the path as an inline
        // record constructor. Regular module-qualified type paths like
        // `Js.Types.tagged_t` must not recursively look up `Js.Types` as a type
        // before reading the module component table.
        let could_be_inline_record_constructor = type_name
            .chars()
            .next()
            .is_some_and(|first| first.is_ascii_uppercase());
        if could_be_inline_record_constructor
            && let Some(parent_decl) =
                lookup_type_decl_for_path_with_cache_mode(parent, env, pers_env, ctx, cache_mode)
        {
            if let crate::types::TypeKind::TypeVariant(ref constrs, layout) = parent_decl.type_kind
            {
                let num_consts = constrs
                    .iter()
                    .filter(|c| {
                        matches!(
                            c.cd_args,
                            crate::types::ConstructorArguments::CstrTuple(ref args)
                                if args.is_empty()
                        )
                    })
                    .count() as i32;
                let num_nonconsts = constrs.len() as i32 - num_consts;
                let mut block_idx = 0i32;
                for (position, cd) in constrs.iter().enumerate() {
                    let is_constant = matches!(
                        cd.cd_args,
                        crate::types::ConstructorArguments::CstrTuple(ref args) if args.is_empty()
                    );

                    if cd.cd_id.name() == type_name.as_str() {
                        if let crate::types::ConstructorArguments::CstrRecord(labels) = &cd.cd_args
                        {
                            let inline_params =
                                inline_record_type_params(ctx, &parent_decl.type_params, labels);
                            return Some(Arc::new(crate::types::TypeDeclaration {
                                type_params: inline_params.clone(),
                                type_arity: inline_params.len() as i32,
                                type_kind: crate::types::TypeKind::TypeRecord(
                                    labels.clone(),
                                    if parent_decl.type_representation
                                        == crate::types::TypeRepresentation::Unboxed
                                    {
                                        crate::types::RecordRepresentation::RecordUnboxed(false)
                                    } else {
                                        crate::types::RecordRepresentation::RecordInlined {
                                            name: type_name.to_string(),
                                            representation: crate::types::ConstructorReference {
                                                variant: layout,
                                                position,
                                            },
                                        }
                                    },
                                ),
                                type_private: parent_decl.type_private,
                                type_manifest: None,
                                type_variance: inline_params
                                    .iter()
                                    .map(|_| crate::types::variance::Variance::full())
                                    .collect(),
                                type_newtype_level: None,
                                type_loc: cd.cd_loc,
                                type_attributes: vec![],
                                type_immediate: false,
                                type_representation: crate::types::TypeRepresentation::Boxed,
                                type_inlined_types: vec![],
                                type_path: None,
                            }));
                        }
                    }

                    if !is_constant {
                        block_idx += 1;
                    }
                }
            }
        }

        if let Some(Some(decl)) = with_resolved_module_components_for_path_with_cache_mode(
            parent,
            env,
            pers_env,
            ctx,
            cache_mode,
            |components| {
                let (_, decl) = match components.lookup_type(type_name.as_str()) {
                    Some(found) => found,
                    None => return None,
                };
                let decl = Arc::new(decl.clone());
                let self_manifest = decl
                    .type_manifest
                    .and_then(|manifest| {
                        let manifest_desc = ctx.get_desc(ctx.repr(manifest));
                        match &*manifest_desc {
                            TypeDesc::Tconstr { path, .. } => Some(path.same(type_path)),
                            _ => None,
                        }
                    })
                    .unwrap_or(false);

                // Functor-application edge case: substituted signatures can expose
                // `type t = M.t` self-manifests. Fall back to the module's raw
                // signature declaration so manifest aliases (for example `Path.t`)
                // remain visible to variant disambiguation.
                if self_manifest {
                    if let Path::Pident(parent_id) = parent.as_ref() {
                        if let Some(md) =
                            lookup_pident_module_for_path(env, parent.as_ref(), parent_id)
                        {
                            // Preserve local alias access paths. For bindings like
                            // `module Functions = WasmBindings__Functions`, deferring
                            // here falls through to the alias target's global
                            // declaration and loses the local path family.
                            if !parent_id.is_persistent()
                                && matches!(
                                    md.md_type,
                                    crate::types::decl::ModuleType::MtyAlias(..)
                                        | crate::types::decl::ModuleType::MtyIdent(..)
                                )
                            {
                                if cache_mode.publishes()
                                    && let Some(cache_key) = cache_key.as_deref()
                                {
                                    ctx.register_resolved_pdot_type(cache_key, decl.clone());
                                }
                                return Some(decl);
                            }
                        }
                    }

                    if let Some(raw_decl) = lookup_raw_type_decl_from_module_path(
                        parent,
                        type_name.as_str(),
                        env,
                        ctx,
                        cache_mode,
                    ) {
                        return Some(raw_decl);
                    }

                    if decl
                        .type_path
                        .as_ref()
                        .is_some_and(|stored_path| !stored_path.same(type_path))
                    {
                        if cache_mode.publishes()
                            && let Some(cache_key) = cache_key.as_deref()
                        {
                            ctx.register_resolved_pdot_type(cache_key, decl.clone());
                        }
                        return Some(decl);
                    }

                    // Keep the substituted declaration as a last-resort fallback,
                    // but continue with alias/module resolution first so functor and
                    // module-alias paths can expose their concrete manifest.
                    deferred_self_manifest_decl = Some(decl);
                    return None;
                }

                // Cache the resolved decl so subsequent lookups for the same
                // Pdot path reuse the same type nodes (matching OCaml's
                // components_of_module_maker lazy caching).
                if cache_mode.publishes()
                    && let Some(cache_key) = cache_key.as_deref()
                {
                    ctx.register_resolved_pdot_type(cache_key, decl.clone());
                }
                Some(decl)
            },
        ) {
            return Some(decl);
        }

        // Resolve the parent module path through local aliases/signatures only
        // after the exact parent path failed. OCaml compiler/ml/env.ml:1000-1007
        // reads `ps_comps` for the requested persistent unit before any alias
        // recovery, so explicit flattened names like `Stdlib_RegExp.t` must not
        // be eagerly rewritten to `Stdlib.RegExp.t`.
        if let Path::Pident(parent_id) = parent.as_ref()
            && let Some(qualified_parent) = pers_env
                .as_ref()
                .and_then(|pers| pers.qualified_alias_path_for_flattened_head(parent_id.name()))
        {
            let qualified_type_path = Path::pdot(qualified_parent, type_name.as_str());
            if !qualified_type_path.same(type_path)
                && let Some(decl) = lookup_type_decl_for_path_with_cache_mode(
                    &qualified_type_path,
                    env,
                    pers_env,
                    ctx,
                    cache_mode,
                )
            {
                if cache_mode.publishes()
                    && let Some(cache_key) = cache_key.as_deref()
                {
                    ctx.register_resolved_pdot_type(cache_key, decl.clone());
                }
                return Some(decl);
            }
        }

        // Try resolving the module alias: Pdot(Pident(Nullable/9), "t")
        // -> look up "Nullable" module in env -> if it's MtyAlias(Stdlib_Nullable)
        // -> look up "Stdlib_Nullable.t" in the path store or try CMI resolution
        if let Path::Pident(parent_id) = parent.as_ref() {
            if let Some(md) = lookup_pident_module_for_path(env, parent.as_ref(), parent_id) {
                use crate::types::decl::ModuleType;
                match &md.md_type {
                    ModuleType::MtyAlias(_, alias_path) | ModuleType::MtyIdent(alias_path) => {
                        let resolved_path = Path::pdot(alias_path.clone(), type_name.as_str());
                        if let Some(decl) = ctx.find_type_decl_by_path(&resolved_path.name()) {
                            return Some(Arc::new(decl.clone()));
                        }
                        if let Some(decl) =
                            crate::types::ctype::resolve_type_through_modules(ctx, &resolved_path)
                        {
                            return Some(Arc::new(decl));
                        }
                    }
                    ModuleType::MtySignature(_) => {
                        let module_path = Path::pident(parent_id.clone());
                        let mut no_persistent_env = None;
                        if let Some(Some(decl)) =
                            with_resolved_module_components_for_path_with_cache_mode(
                                &module_path,
                                env,
                                &mut no_persistent_env,
                                ctx,
                                cache_mode,
                                |components| {
                                    components.lookup_type(type_name.as_str()).map(|(_, decl)| {
                                        let decl = Arc::new(decl.clone());
                                        if cache_mode.publishes()
                                            && let Some(cache_key) = cache_key.as_deref()
                                        {
                                            ctx.register_resolved_pdot_type(
                                                cache_key,
                                                decl.clone(),
                                            );
                                        }
                                        decl
                                    })
                                },
                            )
                        {
                            return Some(decl);
                        }
                    }
                    _ => {}
                }
            }
        }

        // Prefer the substituted declaration we just resolved from the parent
        // signature over global path caches when we hit a self-manifest type.
        if let Some(decl) = deferred_self_manifest_decl.take() {
            return Some(decl);
        }

        // Fall back to direct path lookup only after module-signature resolution.
        // OCaml's Env.components_of_module applies Subst.type_declaration before
        // exposing Sig_type entries; preferring substituted signatures first avoids
        // returning stale unqualified recursive paths (e.g. JSON.t self refs as Pident "t").
        if cache_key.is_some() {
            if let Some(decl) = ctx.find_type_decl_by_path(&path_name) {
                return Some(Arc::new(decl.clone()));
            }
        }

        // Try resolving through modules (loading CMI files on demand)
        if let Some(decl) = crate::types::ctype::resolve_type_through_modules(ctx, type_path) {
            return Some(Arc::new(decl));
        }

        if let Some(decl) = deferred_self_manifest_decl {
            return Some(decl);
        }
    }

    // Only fall back to name-based lookup for simple identifiers.
    // For qualified paths (Pdot), a head-name fallback is unsound and can
    // resolve to an unrelated type that happens to share the same leaf name.
    if let Path::Pident(id) = type_path {
        if let Some(decl) = ctx.find_type_decl(id.name()) {
            return Some(Arc::new(decl.clone()));
        }
    }

    None
}

// ── Comptime Evaluation in Type Checker ─────────────────────────────────────

/// Check if a switch scrutinee is a comptime-known @typeInfo value.
/// If so, resolve the TypeInfo, match against the case patterns, and
/// type-check ONLY the matching branch (skipping non-matching branches).
/// This is critical for comptime: non-matching branches may not type-check
/// (e.g., Json.string(value) where value: user would fail).
fn try_comptime_match(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    _loc: LocIdx,
    scrutinee: &ParsedExpression,
    cases: &[crate::parser::ast::Case],
    expected_ty: TypeExprRef,
    _attributes: &crate::parser::ast::Attributes,
) -> Option<TypeCoreResult<Expression>> {
    // Check if scrutinee is @typeInfo(...)
    let ct_idx = match &*scrutinee.pexp_desc {
        crate::parser::ast::ExpressionDesc::Pexp_comptime_typeinfo(idx) => *idx,
        _ => return None,
    };

    let core_type = tctx.arena.get_core_type(ct_idx);
    let ctx = tctx.type_ctx;

    // First: check if the type argument is a comptime type binding
    // (from `(type t, ...)` parameters). If so, use it directly.
    let type_info_from_binding: Option<crate::types::comptime::TypeInfo> =
        if let crate::parser::ast::CoreTypeDesc::Ptyp_constr(inner) = &*core_type.ptyp_desc {
            let (ref lid, _) = **inner;
            let longident = tctx.arena.get_longident(lid.txt);
            let name = tctx.arena.get_string(longident.last_idx());
            if let Some(crate::types::comptime::ComptimeValue::Type(ti)) =
                tctx.comptime_bindings.get(name).cloned()
            {
                Some(ti)
            } else {
                None
            }
        } else {
            None
        };

    let type_info = if let Some(ti) = type_info_from_binding {
        ti
    } else {
        // Resolve the type (with variable fallback)
        ctx.begin_def();
        let mut resolved_ty = match transl_type(tctx, env, core_type) {
            Ok((_, ty)) => ty,
            Err(_) => {
                ctx.end_def();
                return None;
            }
        };
        ctx.end_def();

        // If type resolves to External (unknown type name), try as variable
        let mut visited_check = Vec::new();
        let check_info =
            crate::types::comptime::build_type_info(ctx, env, resolved_ty, &mut visited_check);
        if matches!(
            check_info,
            crate::types::comptime::TypeInfo::External { .. }
        ) {
            if let crate::parser::ast::CoreTypeDesc::Ptyp_constr(inner) = &*core_type.ptyp_desc {
                let (ref lid, _) = **inner;
                let longident = tctx.arena.get_longident(lid.txt);
                let name = tctx.arena.get_string(longident.last_idx());
                if let Ok(vd) = env.find_value(name) {
                    resolved_ty = vd.val_type;
                }
            }
        }

        // Build TypeInfo
        let mut visited = Vec::new();
        crate::types::comptime::build_type_info(ctx, env, resolved_ty, &mut visited)
    };

    // Determine constructor name
    let ctor_name = match &type_info {
        crate::types::comptime::TypeInfo::Int => "Int",
        crate::types::comptime::TypeInfo::Float => "Float",
        crate::types::comptime::TypeInfo::String => "String",
        crate::types::comptime::TypeInfo::Bool => "Bool",
        crate::types::comptime::TypeInfo::Unit => "Unit",
        crate::types::comptime::TypeInfo::Char => "Char",
        crate::types::comptime::TypeInfo::Bigint => "Bigint",
        crate::types::comptime::TypeInfo::Record { .. } => "Record",
        crate::types::comptime::TypeInfo::Variant { .. } => "Variant",
        crate::types::comptime::TypeInfo::Array { .. } => "Array",
        crate::types::comptime::TypeInfo::Option { .. } => "Option",
        crate::types::comptime::TypeInfo::Function { .. } => "Function",
        crate::types::comptime::TypeInfo::External { .. } => "External",
        crate::types::comptime::TypeInfo::Opaque { .. } => "Opaque",
        _ => return None,
    };

    // Find the matching case by constructor name
    for case in cases {
        let pat = tctx.arena.get_pat(case.pc_lhs);
        let matches = match &*pat.ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_construct(lid, _) => {
                let longident = tctx.arena.get_longident(lid.txt);
                let name = tctx.arena.get_string(longident.last_idx());
                name == ctor_name
            }
            crate::parser::ast::PatternDesc::Ppat_any => true,
            crate::parser::ast::PatternDesc::Ppat_var(_) => true,
            _ => false,
        };

        if matches {
            // Extract destructuring bindings from the pattern and extend env
            let mut body_env = env.clone();
            let pat = tctx.arena.get_pat(case.pc_lhs);
            if let crate::parser::ast::PatternDesc::Ppat_construct(_, Some(arg_pat_idx)) =
                &*pat.ppat_desc
            {
                let arg_pat = tctx.arena.get_pat(*arg_pat_idx);
                // Record({fields, name, ...}) — the arg is a record pattern
                if let crate::parser::ast::PatternDesc::Ppat_record(inner) = &*arg_pat.ppat_desc {
                    let (ref fields, _, _) = **inner;
                    bind_comptime_record_fields(tctx, &mut body_env, fields, &type_info);
                }
            }

            // Type-check ONLY this branch's body in the extended env
            let body = tctx.arena.get_expr(case.pc_rhs);
            match type_expect(tctx, &body_env, body, expected_ty, None) {
                Ok(typed_body) => return Some(Ok(typed_body)),
                Err(e) => return Some(Err(e)),
            }
        }
    }

    None
}

/// Convert a ComptimeValue to a typed tree Expression.
/// Used to substitute comptime-known variables during type checking.
fn comptime_value_to_typed_expr<'a>(
    value: &crate::types::comptime::ComptimeValue,
    ctx: &'a TypeContext,
    env: &Env,
    loc: LocIdx,
) -> Option<Expression> {
    use crate::types::comptime::ComptimeValue;
    let env_ref = ctx.store_typed_env(env);

    match value {
        ComptimeValue::TypedExpr(expr) => {
            return Some(expr.clone());
        }
        ComptimeValue::String(s) => {
            Some(crate::types::comptime::make_string_expr(s, ctx, env, loc))
        }
        ComptimeValue::Int(n) => Some(Expression::new(
            ExpressionDesc::Texp_constant(super::typedtree::Constant::Int(*n)),
            loc,
            ctx.new_constr(crate::types::predef::path_int(), vec![]),
            env_ref,
            crate::parser::ast::Attributes::new(),
        )),
        ComptimeValue::Bool(b) => Some(crate::types::comptime::make_bool_expr(*b, ctx, env, loc)),
        ComptimeValue::Type(type_info) => {
            crate::types::comptime::type_info_to_typed_expr(type_info, ctx, env, loc)
        }
        ComptimeValue::Array(elements) => {
            let elem_exprs: Vec<_> = elements
                .iter()
                .filter_map(|e| comptime_value_to_typed_expr(e, ctx, env, loc))
                .collect();
            Some(Expression::new(
                ExpressionDesc::Texp_array(elem_exprs),
                loc,
                ctx.new_constr(crate::types::predef::path_array(), vec![ctx.new_var(None)]),
                env_ref,
                crate::parser::ast::Attributes::new(),
            ))
        }
        ComptimeValue::Record(entries) => {
            // For comptime records (like fieldInfo), we produce a tuple
            // representation for now
            let exprs: Vec<_> = entries
                .iter()
                .filter_map(|(_, v)| comptime_value_to_typed_expr(v, ctx, env, loc))
                .collect();
            if exprs.is_empty() {
                None
            } else {
                Some(Expression::new(
                    ExpressionDesc::Texp_tuple(exprs),
                    loc,
                    ctx.new_var(None),
                    env_ref,
                    crate::parser::ast::Attributes::new(),
                ))
            }
        }
        _ => None,
    }
}

/// Bind destructured record fields from a comptime typeInfo match into the environment.
/// For `Record({fields, name})`, adds `fields` and `name` as values in the env.
fn bind_comptime_record_fields(
    tctx: &mut TypeCheckContext<'_>,
    env: &mut Env,
    record_fields: &[crate::parser::ast::PatternRecordField],
    type_info: &crate::types::comptime::TypeInfo,
) {
    use crate::types::comptime::TypeInfo;
    let ctx = tctx.type_ctx;

    for field in record_fields {
        let pat = tctx.arena.get_pat(field.pat);
        // Only handle Ppat_var (simple variable binding)
        let var_name = match &*pat.ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_var(name_loc) => {
                tctx.arena.get_string(name_loc.txt).to_string()
            }
            _ => continue,
        };

        // Get the field name from the record pattern
        let field_name = {
            let longident = tctx.arena.get_longident(field.lid.txt);
            tctx.arena.get_string(longident.last_idx()).to_string()
        };

        // Determine the type and create the value based on the typeInfo
        let val_ty = match (type_info, field_name.as_str()) {
            (TypeInfo::Record { name, .. }, "name") => {
                // name: string
                ctx.new_constr(crate::types::predef::path_string(), vec![])
            }
            (TypeInfo::Record { fields, .. }, "fields") => {
                // fields: array<fieldInfo>
                let field_info_ty = ctx.new_constr(crate::types::predef::path_field_info(), vec![]);
                ctx.new_constr(crate::types::predef::path_array(), vec![field_info_ty])
            }
            (TypeInfo::Record { .. }, "unboxed") => {
                // unboxed: bool
                ctx.new_constr(crate::types::predef::path_bool(), vec![])
            }
            (TypeInfo::Variant { name, .. }, "name") => {
                // name: string
                let _ = name;
                ctx.new_constr(crate::types::predef::path_string(), vec![])
            }
            (TypeInfo::Variant { constructors, .. }, "constructors") => {
                // constructors: array<constructorInfo>
                let _ = constructors;
                let field_info_ty = ctx.new_constr(crate::types::predef::path_field_info(), vec![]);
                ctx.new_constr(crate::types::predef::path_array(), vec![field_info_ty])
            }
            (TypeInfo::Variant { .. }, "unboxed") => {
                ctx.new_constr(crate::types::predef::path_bool(), vec![])
            }
            (TypeInfo::Array { .. }, "element") => {
                // element: typeInfo
                ctx.new_constr(crate::types::predef::path_type_info(), vec![])
            }
            (TypeInfo::Option { .. }, "inner") => {
                // inner: typeInfo
                ctx.new_constr(crate::types::predef::path_type_info(), vec![])
            }
            _ => ctx.new_var(None),
        };

        // Add the binding to the environment
        let id = ctx.create_ident(&var_name);
        let vd = crate::types::decl::ValueDescription {
            val_type: val_ty,
            val_kind: crate::types::decl::ValueKind::ValReg,
            val_loc: crate::location::Location::none(),
            val_attributes: vec![],
            val_path: None,
        };
        env.add_value(id, vd);

        // Also add the comptime value so it can be substituted during type checking
        let comptime_val = match (type_info, field_name.as_str()) {
            (TypeInfo::Record { name, .. }, "name") => {
                Some(crate::types::comptime::ComptimeValue::String(name.clone()))
            }
            (TypeInfo::Record { fields, .. }, "fields") => {
                let field_values: Vec<_> = fields
                    .iter()
                    .map(|f| {
                        crate::types::comptime::ComptimeValue::Record(vec![
                            (
                                "name".to_string(),
                                crate::types::comptime::ComptimeValue::String(f.name.clone()),
                            ),
                            (
                                "type".to_string(),
                                crate::types::comptime::ComptimeValue::Type(f.typ.clone()),
                            ),
                            (
                                "typ".to_string(),
                                crate::types::comptime::ComptimeValue::Type(f.typ.clone()),
                            ),
                            (
                                "optional".to_string(),
                                crate::types::comptime::ComptimeValue::Bool(f.optional),
                            ),
                            (
                                "mutable_".to_string(),
                                crate::types::comptime::ComptimeValue::Bool(f.mutable),
                            ),
                        ])
                    })
                    .collect();
                Some(crate::types::comptime::ComptimeValue::Array(field_values))
            }
            (TypeInfo::Record { unboxed, .. }, "unboxed") => {
                Some(crate::types::comptime::ComptimeValue::Bool(*unboxed))
            }
            (TypeInfo::Variant { name, .. }, "name") => {
                Some(crate::types::comptime::ComptimeValue::String(name.clone()))
            }
            (TypeInfo::Variant { constructors, .. }, "constructors") => {
                let ctor_values: Vec<_> = constructors
                    .iter()
                    .map(|c| {
                        let arg_types: Vec<_> = c
                            .args
                            .iter()
                            .map(|t| crate::types::comptime::ComptimeValue::Type(t.clone()))
                            .collect();
                        crate::types::comptime::ComptimeValue::Record(vec![
                            (
                                "name".to_string(),
                                crate::types::comptime::ComptimeValue::String(c.name.clone()),
                            ),
                            (
                                "args".to_string(),
                                crate::types::comptime::ComptimeValue::Array(arg_types),
                            ),
                        ])
                    })
                    .collect();
                Some(crate::types::comptime::ComptimeValue::Array(ctor_values))
            }
            (TypeInfo::Variant { unboxed, .. }, "unboxed") => {
                Some(crate::types::comptime::ComptimeValue::Bool(*unboxed))
            }
            (TypeInfo::Array { element }, "element") => Some(
                crate::types::comptime::ComptimeValue::Type(*element.clone()),
            ),
            (TypeInfo::Option { inner }, "inner") => {
                Some(crate::types::comptime::ComptimeValue::Type(*inner.clone()))
            }
            _ => None,
        };
        if let Some(cv) = comptime_val {
            tctx.comptime_bindings.insert(var_name, cv);
        }
    }
}

/// Check if a function application is a call to a registered @comptime function.
/// If so, inline the function body at the call site. The body will have
/// @typeInfo(T) expanded to literal values by the type checker, and the
/// optimizer handles switch elimination and constant folding.
///
/// Monomorphization: each unique (function, type-key) pair produces one
/// specialized function. Recursive types terminate because re-entering
/// the same pair emits a self-reference instead of expanding again.
fn try_comptime_application(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    _loc: LocIdx,
    funct_expr: &ParsedExpression,
    args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
    expected_ty: TypeExprRef,
) -> Option<TypeCoreResult<Expression>> {
    // Check if the function is a simple identifier
    let func_name = match &*funct_expr.pexp_desc {
        crate::parser::ast::ExpressionDesc::Pexp_ident(lid) => {
            let longident = tctx.arena.get_longident(lid.txt);
            tctx.arena.get_string(longident.last_idx()).to_string()
        }
        _ => return None,
    };

    // Check if it's a registered comptime function
    let comptime_fn = tctx.comptime_functions.get(&func_name)?.clone();

    // Safety: depth limit as fallback (monomorph cache is the primary guard)
    static COMPTIME_DEPTH: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
    let depth = COMPTIME_DEPTH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    if depth > 200 {
        COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
        return None;
    }

    // Extract function parameters and body from parse tree
    let body_expr = tctx.arena.get_expr(comptime_fn.body_expr_idx);
    let (params, inner_body) = extract_function_params_and_body(body_expr, tctx.arena);

    // Save comptime bindings so we can restore after specialization
    let saved_bindings = tctx.comptime_bindings.clone();

    // ── Phase 1: Type-check arguments and determine the type key ──

    let ctx = tctx.type_ctx;
    let mut typed_args: Vec<(String, Expression, bool)> = Vec::new(); // (name, typed_arg, is_type)
    let mut explicit_type_keys: Vec<crate::types::comptime::TypeInfo> = Vec::new();
    let mut first_value_type: Option<crate::types::comptime::TypeInfo> = None;
    let has_type_params = params.iter().any(|p| p.is_type);

    for (i, (_label, arg_idx)) in args.iter().enumerate() {
        let param = params.get(i);
        let is_type_param = param.map_or(false, |p| p.is_type);
        let param_name = param.map_or(format!("__arg{i}"), |p| p.name.clone());

        if is_type_param {
            // Type parameter: resolve as a type name, not a value
            let arg_expr = tctx.arena.get_expr(*arg_idx);
            let type_info = resolve_comptime_type_arg(tctx, env, arg_expr);
            if let Some(ti) = type_info {
                explicit_type_keys.push(ti.clone());
                // Bind as ComptimeValue::Type for @typeInfo resolution
                tctx.comptime_bindings.insert(
                    param_name.clone(),
                    crate::types::comptime::ComptimeValue::Type(ti),
                );
                // Create a dummy typed expression for the type arg
                // (type params are erased at runtime)
                let dummy = Expression::new(
                    ExpressionDesc::Texp_constant(Constant::Int(0)),
                    LocIdx(0),
                    ctx.new_var(None),
                    EnvRef(0),
                    Attributes::new(),
                );
                typed_args.push((param_name, dummy, true));
            } else {
                tctx.comptime_bindings = saved_bindings;
                COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
                return None;
            }
        } else {
            // Value parameter: type-check normally
            let arg_expr = tctx.arena.get_expr(*arg_idx);
            let arg_ty = ctx.new_var(None);
            match type_expect(tctx, env, arg_expr, arg_ty, None) {
                Ok(typed_arg) => {
                    if first_value_type.is_none() {
                        // Use the first value's type for the implicit type key
                        first_value_type = Some(crate::types::comptime::build_type_info(
                            ctx,
                            env,
                            typed_arg.exp_type,
                            &mut vec![],
                        ));
                    }
                    typed_args.push((param_name, typed_arg, false));
                }
                Err(_) => {
                    tctx.comptime_bindings = saved_bindings;
                    COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
                    return None;
                }
            }
        }
    }

    // Type key: explicit type params if any, otherwise the first value's type.
    // Decoder: decode(user, json) → key=user (explicit)
    // Encoder: encode(alice) → key=user (implicit from alice's type)
    let type_key = if has_type_params {
        if explicit_type_keys.len() == 1 {
            explicit_type_keys[0].clone()
        } else if explicit_type_keys.is_empty() {
            crate::types::comptime::TypeInfo::Unit
        } else {
            crate::types::comptime::TypeInfo::Tuple {
                elements: explicit_type_keys,
            }
        }
    } else {
        first_value_type.unwrap_or(crate::types::comptime::TypeInfo::Unit)
    };

    let gen_name = crate::types::comptime::make_monomorph_name(&func_name, &type_key);

    // Collect the runtime args (non-type args) for the call site
    let runtime_args: Vec<_> = typed_args
        .iter()
        .filter(|(_, _, is_type)| !is_type)
        .map(|(_, arg, _)| arg.clone())
        .collect();

    // ── Phase 2: Check monomorphization cache ──

    // Already completed? Just emit a call.
    if tctx.monomorph_cache.lookup(&func_name, &type_key).is_some() {
        tctx.comptime_bindings = saved_bindings;
        COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
        return Some(Ok(make_comptime_call(
            tctx,
            &gen_name,
            &runtime_args,
            expected_ty,
        )));
    }

    // Recursive: in-progress for the same type? Emit forward reference.
    if tctx.monomorph_cache.is_in_progress(&func_name, &type_key) {
        tctx.comptime_bindings = saved_bindings;
        COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);
        return Some(Ok(make_comptime_call(
            tctx,
            &gen_name,
            &runtime_args,
            expected_ty,
        )));
    }

    // ── Phase 3: Specialize — produce a named monomorphized function ──

    tctx.monomorph_cache.begin(&func_name, &type_key);

    // Set up environment with argument bindings
    let mut spec_env = env.clone();
    let mut runtime_param_name = "value".to_string();
    let mut runtime_param_type = ctx.new_var(None);
    let mut runtime_param_ident: Option<crate::ident::Ident> = None;

    for (name, typed_arg, is_type) in &typed_args {
        if *is_type {
            // Type params already bound as ComptimeValue::Type above
        } else {
            runtime_param_name = name.clone();
            runtime_param_type = typed_arg.exp_type;
            // Add parameter to env so body type-checks with the right type.
            // Do NOT add to comptime_bindings — the parameter should remain
            // as a variable reference in the generated function body, not be
            // substituted with the call-site argument value.
            let id = ctx.create_ident(name);
            runtime_param_ident = Some(id.clone());
            let vd = crate::types::decl::ValueDescription {
                val_type: typed_arg.exp_type,
                val_kind: crate::types::decl::ValueKind::ValReg,
                val_loc: crate::location::Location::none(),
                val_attributes: vec![],
                val_path: None,
            };
            spec_env.add_value(id, vd);
        }
    }

    // Type-check the body (may trigger recursive calls that hit the cache)
    let body_result = type_expect(tctx, &spec_env, &inner_body, expected_ty, None);

    tctx.comptime_bindings = saved_bindings;
    COMPTIME_DEPTH.fetch_sub(1, std::sync::atomic::Ordering::Relaxed);

    match body_result {
        Ok(typed_body) => {
            let return_type = typed_body.exp_type;
            let recursive = contains_ident_reference(&typed_body, &gen_name);
            let gen_ident = ctx.create_ident(&gen_name);

            let param_ident =
                runtime_param_ident.unwrap_or_else(|| ctx.create_ident(&runtime_param_name));
            tctx.monomorph_cache.complete(
                &func_name,
                &type_key,
                gen_name.clone(),
                crate::types::comptime::GeneratedFunction {
                    name: gen_name.clone(),
                    ident: gen_ident,
                    body: typed_body,
                    param_name: runtime_param_name,
                    param_ident,
                    param_type: runtime_param_type,
                    return_type,
                    recursive,
                },
            );

            Some(Ok(make_comptime_call(
                tctx,
                &gen_name,
                &runtime_args,
                expected_ty,
            )))
        }
        Err(_) => None,
    }
}

/// Fallback: inline-at-call-site for comptime functions without type-bearing params.
fn try_comptime_application_inline(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    _func_name: &str,
    _comptime_fn: &crate::types::comptime::ComptimeFunction,
    args: &[(ArgLabel, crate::parse_arena::ExprIdx)],
    expected_ty: TypeExprRef,
    params: &[crate::types::comptime::ComptimeParam],
    inner_body: &ParsedExpression,
) -> Option<TypeCoreResult<Expression>> {
    let saved_bindings = tctx.comptime_bindings.clone();
    let mut inline_env = env.clone();
    let ctx = tctx.type_ctx;

    for (i, (_label, arg_idx)) in args.iter().enumerate() {
        let arg_expr = tctx.arena.get_expr(*arg_idx);
        let arg_ty = ctx.new_var(None);
        match type_expect(tctx, &inline_env, arg_expr, arg_ty, None) {
            Ok(typed_arg) => {
                if let Some(param) = params.get(i) {
                    let id = ctx.create_ident(&param.name);
                    let vd = crate::types::decl::ValueDescription {
                        val_type: typed_arg.exp_type,
                        val_kind: crate::types::decl::ValueKind::ValReg,
                        val_loc: crate::location::Location::none(),
                        val_attributes: vec![],
                        val_path: None,
                    };
                    inline_env.add_value(id, vd);
                    tctx.comptime_bindings.insert(
                        param.name.clone(),
                        crate::types::comptime::ComptimeValue::TypedExpr(typed_arg.clone()),
                    );
                }
            }
            Err(_) => {
                tctx.comptime_bindings = saved_bindings;
                return None;
            }
        }
    }

    let result = match type_expect(tctx, &inline_env, inner_body, expected_ty, None) {
        Ok(typed_expr) => Some(Ok(typed_expr)),
        Err(_) => None,
    };

    tctx.comptime_bindings = saved_bindings;
    result
}

/// Resolve a call-site argument as a comptime type.
/// Handles:
///   - `decode(user, json)` — resolves `user` as a type name
///   - `decode(t, json)` — resolves `t` as a comptime type binding
///   - `decode(field.type, json)` — resolves a record field access on a
///     comptime Record binding (from `inline for field in fields { ... }`)
fn resolve_comptime_type_arg(
    tctx: &TypeCheckContext<'_>,
    env: &Env,
    arg_expr: &ParsedExpression,
) -> Option<crate::types::comptime::TypeInfo> {
    use crate::parser::ast::ExpressionDesc;
    use crate::types::comptime::{ComptimeValue, TypeInfo};

    match &*arg_expr.pexp_desc {
        ExpressionDesc::Pexp_ident(lid) => {
            let longident = tctx.arena.get_longident(lid.txt);
            let name = tctx.arena.get_string(longident.last_idx());

            // Check comptime type bindings first (for `t` where t is a comptime type param)
            if let Some(ComptimeValue::Type(ti)) = tctx.comptime_bindings.get(name) {
                return Some(ti.clone());
            }

            // Try as a type in the environment
            if let Ok((id, _decl)) = env.find_type_with_id(name) {
                let ty = tctx
                    .type_ctx
                    .new_constr(crate::types::Path::Pident(id.clone()), vec![]);
                return Some(crate::types::comptime::build_type_info(
                    tctx.type_ctx,
                    env,
                    ty,
                    &mut vec![],
                ));
            }
            // Try as a primitive type name
            match name {
                "string" => Some(TypeInfo::String),
                "int" => Some(TypeInfo::Int),
                "float" => Some(TypeInfo::Float),
                "bool" => Some(TypeInfo::Bool),
                "unit" => Some(TypeInfo::Unit),
                "char" => Some(TypeInfo::Char),
                _ => None,
            }
        }
        ExpressionDesc::Pexp_field(record_expr_idx, field_lid) => {
            // field.type — look up the record in comptime_bindings, find the "type" entry
            let record_expr = tctx.arena.get_expr(*record_expr_idx);
            if let ExpressionDesc::Pexp_ident(rec_lid) = &*record_expr.pexp_desc {
                let rec_longident = tctx.arena.get_longident(rec_lid.txt);
                if rec_longident.is_simple() {
                    let rec_name = tctx.arena.get_string(rec_longident.last_idx());
                    if let Some(ComptimeValue::Record(entries)) =
                        tctx.comptime_bindings.get(rec_name)
                    {
                        let field_name = {
                            let fl = tctx.arena.get_longident(field_lid.txt);
                            tctx.arena.get_string(fl.last_idx()).to_string()
                        };
                        if let Some((_, ComptimeValue::Type(ti))) =
                            entries.iter().find(|(k, _)| k == &field_name)
                        {
                            return Some(ti.clone());
                        }
                    }
                }
            }
            None
        }
        _ => None,
    }
}

/// Check if an expression tree contains @buildVariant (possibly nested in
/// switch/match branches, or via a call to a @comptime function whose body
/// contains one). Used to detect @comptime let bindings that should be
/// emitted as type declarations rather than registered as comptime functions.
pub fn contains_build_variant(
    expr: &ParsedExpression,
    arena: &crate::parse_arena::ParseArena,
) -> bool {
    contains_build_variant_with_registry(expr, arena, None)
}

/// Like contains_build_variant, but can follow calls to registered @comptime
/// functions (provided via the registry) to check their bodies.
pub fn contains_build_variant_with_registry(
    expr: &ParsedExpression,
    arena: &crate::parse_arena::ParseArena,
    registry: Option<&ahash::AHashMap<String, crate::types::comptime::ComptimeFunction>>,
) -> bool {
    use crate::parser::ast::ExpressionDesc as ED;
    // Top-level: if this is a function (has parameters), it's a TEMPLATE,
    // not a type declaration. Return false so it registers as a function.
    if matches!(&*expr.pexp_desc, ED::Pexp_fun(_) | ED::Pexp_newtype(_)) {
        return false;
    }
    contains_build_variant_inside(expr, arena, registry)
}

/// Inner check that DOES follow through function-parameter wrappers.
fn contains_build_variant_inside(
    expr: &ParsedExpression,
    arena: &crate::parse_arena::ParseArena,
    registry: Option<&ahash::AHashMap<String, crate::types::comptime::ComptimeFunction>>,
) -> bool {
    use crate::parser::ast::ExpressionDesc as ED;
    match &*expr.pexp_desc {
        ED::Pexp_comptime_build_variant(_) | ED::Pexp_comptime_build_record(_) => true,
        ED::Pexp_fun(inner) => {
            contains_build_variant_inside(arena.get_expr(inner.rhs), arena, registry)
        }
        ED::Pexp_newtype(inner) => {
            let (_, ref body) = **inner;
            contains_build_variant_inside(arena.get_expr(*body), arena, registry)
        }
        ED::Pexp_match(inner) => {
            let (_, ref cases) = **inner;
            cases
                .iter()
                .any(|c| contains_build_variant_inside(arena.get_expr(c.pc_rhs), arena, registry))
        }
        ED::Pexp_ifthenelse(inner) => {
            let (_, then_idx, else_opt) = &**inner;
            contains_build_variant_inside(arena.get_expr(*then_idx), arena, registry)
                || else_opt.map_or(false, |e| {
                    contains_build_variant_inside(arena.get_expr(e), arena, registry)
                })
        }
        ED::Pexp_apply(inner) => {
            if let Some(reg) = registry {
                let funct_expr = arena.get_expr(inner.funct);
                if let ED::Pexp_ident(lid) = &*funct_expr.pexp_desc {
                    let longident = arena.get_longident(lid.txt);
                    let name = arena.get_string(longident.last_idx());
                    if let Some(cf) = reg.get(name) {
                        let callee_body = arena.get_expr(cf.body_expr_idx);
                        return contains_build_variant_inside(callee_body, arena, registry);
                    }
                }
            }
            false
        }
        _ => false,
    }
}

/// Normalize an expression into `(pattern, collection, body)` form as if it
/// were `inline for pat in collection { body }`. Handles:
/// - `inline for pat in collection { body }` (direct)
/// - `Array.map(collection, pat => body)` (syntactic sugar)
/// - `collection->Array.map(pat => body)` (pipe form — pre-expanded by parser)
///
/// Returns None if the expression is neither form.
pub fn as_comptime_loop(
    expr: &ParsedExpression,
    arena: &crate::parse_arena::ParseArena,
) -> Option<(
    crate::parse_arena::PatIdx,
    crate::parse_arena::ExprIdx,
    crate::parse_arena::ExprIdx,
)> {
    use crate::parser::ast::ExpressionDesc as ED;

    match &*expr.pexp_desc {
        ED::Pexp_inline_for(inner) => {
            let (pat_idx, coll_idx, body_idx) = **inner;
            Some((pat_idx, coll_idx, body_idx))
        }
        ED::Pexp_apply(inner) => {
            let crate::parser::ast::PexpApply { funct, args, .. } = &**inner;
            let funct_expr = arena.get_expr(*funct);

            // Check if the function is Array.map (or just map)
            let is_array_map = if let ED::Pexp_ident(lid) = &*funct_expr.pexp_desc {
                let longident = arena.get_longident(lid.txt);
                let last_name = arena.get_string(longident.last_idx());
                if last_name != "map" {
                    return None;
                }
                // Check that module prefix is "Array" (or no prefix — just `map`)
                let parts: Vec<String> = longident
                    .flatten_idx()
                    .iter()
                    .map(|idx| arena.get_string(*idx).to_string())
                    .collect();
                parts.len() == 1 || (parts.len() == 2 && parts[0] == "Array")
            } else {
                false
            };

            if !is_array_map || args.len() != 2 {
                return None;
            }

            // First arg: collection; second arg: lambda
            let coll_idx = args[0].1;
            let lambda_expr = arena.get_expr(args[1].1);

            if let ED::Pexp_fun(fun_inner) = &*lambda_expr.pexp_desc {
                // Single-parameter lambda: (pat) => body
                Some((fun_inner.lhs, coll_idx, fun_inner.rhs))
            } else {
                None
            }
        }
        _ => None,
    }
}

/// Evaluate a type-builder expression to a TypeBuilderResult.
/// Used for @comptime type declarations — the body should produce a TypeKind.
///
/// Handles:
/// - `@buildVariant(array_expr)` → TypeBuilderResult::Variant(constructor_names)
/// - `@variantCase({name: "X"})` → single VariantCaseSpec (used inside @buildVariant)
/// - `switch @typeInfo(t) { ... }` → pick matching branch, recurse
/// - `inline for x in arr { ... }` → unroll, collect results
pub fn evaluate_type_builder(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<crate::types::comptime::TypeBuilderResult> {
    use crate::parser::ast::ExpressionDesc as ED;
    use crate::types::comptime::{TypeBuilderResult, VariantCaseSpec};

    match &*expr.pexp_desc {
        ED::Pexp_comptime_build_variant(inner_idx) => {
            // @buildVariant(arrayOrInlineFor) — collect variant cases, build variant type
            let inner_expr = tctx.arena.get_expr(*inner_idx);
            let cases = evaluate_variant_cases(tctx, env, inner_expr)?;
            let names: Vec<String> = cases.into_iter().map(|c| c.name).collect();
            Ok(TypeBuilderResult::Variant(names))
        }
        ED::Pexp_comptime_build_record(inner_idx) => {
            // @buildRecord(arrayOrInlineFor) — collect fields, build record type
            let inner_expr = tctx.arena.get_expr(*inner_idx);
            let fields = evaluate_record_fields(tctx, env, inner_expr)?;
            Ok(TypeBuilderResult::Record(fields))
        }
        ED::Pexp_match(match_inner) => {
            let (ref scrut_idx, ref cases) = **match_inner;
            // switch @typeInfo(t) { ... } — pick the matching branch
            let scrut = tctx.arena.get_expr(*scrut_idx);
            if let ED::Pexp_comptime_typeinfo(ct_idx) = &*scrut.pexp_desc {
                let core_type = tctx.arena.get_core_type(*ct_idx);
                let type_info = resolve_typeinfo_in_builder(tctx, env, core_type)?;
                let ctor_name = constructor_name_of(&type_info);
                for case in cases {
                    let pat = tctx.arena.get_pat(case.pc_lhs);
                    let matches = match &*pat.ppat_desc {
                        crate::parser::ast::PatternDesc::Ppat_construct(lid, _) => {
                            let pat_name = {
                                let longident = tctx.arena.get_longident(lid.txt);
                                tctx.arena.get_string(longident.last_idx()).to_string()
                            };
                            pat_name == ctor_name
                        }
                        crate::parser::ast::PatternDesc::Ppat_any => true,
                        crate::parser::ast::PatternDesc::Ppat_var(_) => true,
                        _ => false,
                    };
                    if matches {
                        // Bind destructured fields (like Record({fields}))
                        let saved_bindings = tctx.comptime_bindings.clone();
                        let mut branch_env = env.clone();
                        if let crate::parser::ast::PatternDesc::Ppat_construct(
                            _,
                            Some(arg_pat_idx),
                        ) = &*pat.ppat_desc
                        {
                            let arg_pat = tctx.arena.get_pat(*arg_pat_idx);
                            if let crate::parser::ast::PatternDesc::Ppat_record(rec_inner) =
                                &*arg_pat.ppat_desc
                            {
                                let (ref fields, _, _) = **rec_inner;
                                bind_comptime_record_fields(
                                    tctx,
                                    &mut branch_env,
                                    fields,
                                    &type_info,
                                );
                            }
                        }
                        let body_expr = tctx.arena.get_expr(case.pc_rhs);
                        let result = evaluate_type_builder(tctx, &branch_env, body_expr);
                        tctx.comptime_bindings = saved_bindings;
                        return result;
                    }
                }
                Err(super::TypeCoreError::Other(
                    "evaluate_type_builder: no matching switch branch".into(),
                ))
            } else {
                Err(super::TypeCoreError::Other(
                    "evaluate_type_builder: switch scrutinee must be @typeInfo(...)".into(),
                ))
            }
        }
        ED::Pexp_comptime_compile_error(msg_idx) => {
            let msg_expr = tctx.arena.get_expr(*msg_idx);
            let msg = if let ED::Pexp_constant(c) = &*msg_expr.pexp_desc {
                if let crate::parser::ast::Constant::String(s, _) = &**c {
                    s.to_string()
                } else {
                    "<non-string message>".to_string()
                }
            } else {
                "<dynamic message>".to_string()
            };
            Err(super::TypeCoreError::Other(format!("@compileError: {msg}")))
        }
        ED::Pexp_apply(inner) => {
            // Comptime call: keysOf(user) where keysOf is a registered @comptime function
            let crate::parser::ast::PexpApply {
                ref funct,
                ref args,
                ..
            } = **inner;
            let funct_expr = tctx.arena.get_expr(*funct);
            let func_name = match &*funct_expr.pexp_desc {
                ED::Pexp_ident(lid) => {
                    let longident = tctx.arena.get_longident(lid.txt);
                    tctx.arena.get_string(longident.last_idx()).to_string()
                }
                _ => {
                    return Err(super::TypeCoreError::Other(
                        "evaluate_type_builder: call target must be a simple identifier".into(),
                    ));
                }
            };
            let comptime_fn = tctx
                .comptime_functions
                .get(&func_name)
                .cloned()
                .ok_or_else(|| {
                    super::TypeCoreError::Other(format!(
                        "evaluate_type_builder: '{}' is not a registered @comptime function",
                        func_name
                    ))
                })?;

            // Extract the function's parameters and body
            let body_expr_idx = comptime_fn.body_expr_idx;
            let body_expr = tctx.arena.get_expr(body_expr_idx);
            let (params, inner_body) = extract_function_params_and_body(body_expr, tctx.arena);

            // Bind each argument
            let saved_bindings = tctx.comptime_bindings.clone();
            for (i, (_label, arg_idx)) in args.iter().enumerate() {
                let param = params.get(i);
                if let Some(p) = param {
                    if p.is_type {
                        let arg_expr = tctx.arena.get_expr(*arg_idx);
                        let type_info =
                            resolve_comptime_type_arg(tctx, env, arg_expr).ok_or_else(|| {
                                super::TypeCoreError::Other(format!(
                                    "evaluate_type_builder: could not resolve type arg for '{}'",
                                    p.name
                                ))
                            })?;
                        tctx.comptime_bindings.insert(
                            p.name.clone(),
                            crate::types::comptime::ComptimeValue::Type(type_info),
                        );
                    }
                    // Non-type params not supported in type-builder calls yet
                }
            }

            // Recursively evaluate the body
            let result = evaluate_type_builder(tctx, env, &inner_body);
            tctx.comptime_bindings = saved_bindings;
            result
        }
        other => {
            let kind = match other {
                ED::Pexp_ident(_) => "Pexp_ident",
                ED::Pexp_constant(_) => "Pexp_constant",
                ED::Pexp_fun(_) => "Pexp_fun",
                ED::Pexp_newtype(_) => "Pexp_newtype",
                ED::Pexp_let(_) => "Pexp_let",
                ED::Pexp_construct(_, _) => "Pexp_construct",
                ED::Pexp_tuple(_) => "Pexp_tuple",
                ED::Pexp_array(_) => "Pexp_array",
                ED::Pexp_record(_) => "Pexp_record",
                ED::Pexp_field(_, _) => "Pexp_field",
                ED::Pexp_sequence(_, _) => "Pexp_sequence",
                _ => "other",
            };
            Err(super::TypeCoreError::Other(format!(
                "evaluate_type_builder: unsupported expression kind '{kind}'",
            )))
        }
    }
}

/// Evaluate an expression that should produce a list of variant cases.
/// Handles array literals and inline-for expressions.
fn evaluate_variant_cases(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<Vec<crate::types::comptime::VariantCaseSpec>> {
    use crate::parser::ast::ExpressionDesc as ED;
    use crate::types::comptime::VariantCaseSpec;

    // Check for inline for OR Array.map (treated equivalently)
    if let Some((pat_idx, collection_idx, body_idx)) = as_comptime_loop(expr, tctx.arena) {
        let coll_expr = tctx.arena.get_expr(collection_idx);
        let comptime_array = match &*coll_expr.pexp_desc {
            ED::Pexp_ident(lid) => {
                let longident = tctx.arena.get_longident(lid.txt);
                if longident.is_simple() {
                    let vname = tctx.arena.get_string(longident.last_idx());
                    match tctx.comptime_bindings.get(vname) {
                        Some(crate::types::comptime::ComptimeValue::Array(elements)) => {
                            Some(elements.clone())
                        }
                        _ => None,
                    }
                } else {
                    None
                }
            }
            _ => None,
        }
        .ok_or_else(|| {
            super::TypeCoreError::Other(
                "evaluate_variant_cases: loop collection must be comptime-known".into(),
            )
        })?;

        let pat = tctx.arena.get_pat(pat_idx);
        let var_name = match &*pat.ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_var(name_loc) => {
                tctx.arena.get_string(name_loc.txt).to_string()
            }
            _ => "__case".to_string(),
        };
        let body_expr = tctx.arena.get_expr(body_idx);
        let saved = tctx.comptime_bindings.clone();
        let mut cases = Vec::new();
        for element in &comptime_array {
            tctx.comptime_bindings
                .insert(var_name.clone(), element.clone());
            cases.push(evaluate_single_variant_case(tctx, env, body_expr)?);
        }
        tctx.comptime_bindings = saved;
        return Ok(cases);
    }

    match &*expr.pexp_desc {
        ED::Pexp_array(exprs) => {
            let mut cases = Vec::new();
            for e_idx in exprs.iter() {
                let e = tctx.arena.get_expr(*e_idx);
                cases.push(evaluate_single_variant_case(tctx, env, e)?);
            }
            Ok(cases)
        }
        _ => {
            // Single case (not array) — just evaluate it
            Ok(vec![evaluate_single_variant_case(tctx, env, expr)?])
        }
    }
}

/// Evaluate a single @variantCase({name: ...}) expression.
fn evaluate_single_variant_case(
    tctx: &mut TypeCheckContext<'_>,
    _env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<crate::types::comptime::VariantCaseSpec> {
    use crate::parser::ast::ExpressionDesc as ED;

    // Expected form: @variantCase({name: ..., ...})
    let rec_idx = match &*expr.pexp_desc {
        ED::Pexp_comptime_variant_case(e) => *e,
        _ => {
            return Err(super::TypeCoreError::Other(
                "evaluate_variant_cases: expected @variantCase({...})".into(),
            ));
        }
    };

    let rec_expr = tctx.arena.get_expr(rec_idx);
    // The record literal: {name: "Name"}
    if let ED::Pexp_record(inner) = &*rec_expr.pexp_desc {
        let (ref fields, _) = **inner;
        for field in fields {
            let fname = {
                let longident = tctx.arena.get_longident(field.lid.txt);
                tctx.arena.get_string(longident.last_idx()).to_string()
            };
            if fname == "name" {
                // Evaluate the value — should be a comptime-known string
                let val_expr = tctx.arena.get_expr(field.expr);
                let name_str = evaluate_comptime_string(tctx, val_expr)?;
                // Capitalize the first letter to make a valid constructor name
                let capitalized = capitalize_first(&name_str);
                return Ok(crate::types::comptime::VariantCaseSpec { name: capitalized });
            }
        }
    }
    Err(super::TypeCoreError::Other(
        "@variantCase: expected {name: \"...\"}".into(),
    ))
}

/// Evaluate an expression producing a list of record field descriptors.
fn evaluate_record_fields(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<Vec<crate::types::comptime::RecordFieldSpec>> {
    use crate::parser::ast::ExpressionDesc as ED;

    // Check for inline for OR Array.map
    if let Some((pat_idx, collection_idx, body_idx)) = as_comptime_loop(expr, tctx.arena) {
        let coll_expr = tctx.arena.get_expr(collection_idx);
        let comptime_array = match &*coll_expr.pexp_desc {
            ED::Pexp_ident(lid) => {
                let longident = tctx.arena.get_longident(lid.txt);
                if longident.is_simple() {
                    let vname = tctx.arena.get_string(longident.last_idx());
                    match tctx.comptime_bindings.get(vname) {
                        Some(crate::types::comptime::ComptimeValue::Array(elements)) => {
                            Some(elements.clone())
                        }
                        _ => None,
                    }
                } else {
                    None
                }
            }
            _ => None,
        }
        .ok_or_else(|| {
            super::TypeCoreError::Other(
                "evaluate_record_fields: loop collection must be comptime-known".into(),
            )
        })?;

        let pat = tctx.arena.get_pat(pat_idx);
        let var_name = match &*pat.ppat_desc {
            crate::parser::ast::PatternDesc::Ppat_var(name_loc) => {
                tctx.arena.get_string(name_loc.txt).to_string()
            }
            _ => "__field".to_string(),
        };
        let body_expr = tctx.arena.get_expr(body_idx);
        let saved = tctx.comptime_bindings.clone();
        let mut out = Vec::new();
        for element in &comptime_array {
            tctx.comptime_bindings
                .insert(var_name.clone(), element.clone());
            out.push(evaluate_single_record_field(tctx, env, body_expr)?);
        }
        tctx.comptime_bindings = saved;
        return Ok(out);
    }

    match &*expr.pexp_desc {
        ED::Pexp_array(exprs) => {
            let mut out = Vec::new();
            for e_idx in exprs.iter() {
                let e = tctx.arena.get_expr(*e_idx);
                out.push(evaluate_single_record_field(tctx, env, e)?);
            }
            Ok(out)
        }
        _ => Ok(vec![evaluate_single_record_field(tctx, env, expr)?]),
    }
}

/// Evaluate a single @recordField({name, typ, optional?, mutable_?}) expression.
fn evaluate_single_record_field(
    tctx: &mut TypeCheckContext<'_>,
    _env: &Env,
    expr: &ParsedExpression,
) -> TypeCoreResult<crate::types::comptime::RecordFieldSpec> {
    use crate::parser::ast::ExpressionDesc as ED;

    let rec_idx = match &*expr.pexp_desc {
        ED::Pexp_comptime_record_field(e) => *e,
        _ => {
            return Err(super::TypeCoreError::Other(
                "evaluate_record_fields: expected @recordField({...})".into(),
            ));
        }
    };

    let rec_expr = tctx.arena.get_expr(rec_idx);
    if let ED::Pexp_record(inner) = &*rec_expr.pexp_desc {
        let (ref fields, _) = **inner;
        let mut name = None;
        let mut typ = None;
        let mut optional = false;
        let mut mutable_ = false;
        for field in fields {
            let fname = {
                let longident = tctx.arena.get_longident(field.lid.txt);
                tctx.arena.get_string(longident.last_idx()).to_string()
            };
            let val_expr = tctx.arena.get_expr(field.expr);
            match fname.as_str() {
                "name" => name = Some(evaluate_comptime_string(tctx, val_expr)?),
                "typ" | "type" => {
                    // Expect an expression that resolves to a comptime Type
                    if let Some(ti) = resolve_comptime_type_arg(tctx, _env, val_expr) {
                        typ = Some(ti);
                    }
                }
                "optional" => {
                    if let ED::Pexp_construct(lid, _) = &*val_expr.pexp_desc {
                        let longident = tctx.arena.get_longident(lid.txt);
                        let n = tctx.arena.get_string(longident.last_idx());
                        if n == "true" {
                            optional = true;
                        }
                    }
                }
                "mutable_" => {
                    if let ED::Pexp_construct(lid, _) = &*val_expr.pexp_desc {
                        let longident = tctx.arena.get_longident(lid.txt);
                        let n = tctx.arena.get_string(longident.last_idx());
                        if n == "true" {
                            mutable_ = true;
                        }
                    }
                }
                _ => {}
            }
        }
        let name = name.ok_or_else(|| {
            super::TypeCoreError::Other("@recordField: missing required 'name'".into())
        })?;
        let typ = typ.ok_or_else(|| {
            super::TypeCoreError::Other("@recordField: missing required 'typ'".into())
        })?;
        return Ok(crate::types::comptime::RecordFieldSpec {
            name,
            typ,
            optional,
            mutable_,
        });
    }
    Err(super::TypeCoreError::Other(
        "@recordField: expected {name: \"...\", typ: ..., optional?: bool}".into(),
    ))
}

/// Evaluate an expression that should be a comptime-known string.
fn evaluate_comptime_string(
    tctx: &TypeCheckContext<'_>,
    expr: &ParsedExpression,
) -> TypeCoreResult<String> {
    use crate::parser::ast::ExpressionDesc as ED;

    match &*expr.pexp_desc {
        ED::Pexp_constant(c) => {
            if let crate::parser::ast::Constant::String(s, _) = &**c {
                Ok(s.to_string())
            } else {
                Err(super::TypeCoreError::Other(
                    "expected string literal".into(),
                ))
            }
        }
        ED::Pexp_ident(lid) => {
            let longident = tctx.arena.get_longident(lid.txt);
            let name = tctx.arena.get_string(longident.last_idx());
            if let Some(crate::types::comptime::ComptimeValue::String(s)) =
                tctx.comptime_bindings.get(name)
            {
                Ok(s.clone())
            } else {
                Err(super::TypeCoreError::Other(format!(
                    "expected comptime string, got variable '{}'",
                    name
                )))
            }
        }
        ED::Pexp_field(rec_idx, field_lid) => {
            // field.name — look up in comptime bindings
            let rec_expr = tctx.arena.get_expr(*rec_idx);
            if let ED::Pexp_ident(rec_lid) = &*rec_expr.pexp_desc {
                let rec_longident = tctx.arena.get_longident(rec_lid.txt);
                if rec_longident.is_simple() {
                    let rec_name = tctx.arena.get_string(rec_longident.last_idx());
                    if let Some(crate::types::comptime::ComptimeValue::Record(entries)) =
                        tctx.comptime_bindings.get(rec_name)
                    {
                        let field_name = {
                            let fl = tctx.arena.get_longident(field_lid.txt);
                            tctx.arena.get_string(fl.last_idx()).to_string()
                        };
                        if let Some((_, crate::types::comptime::ComptimeValue::String(s))) =
                            entries.iter().find(|(k, _)| k == &field_name)
                        {
                            return Ok(s.clone());
                        }
                    }
                }
            }
            Err(super::TypeCoreError::Other(
                "expected comptime string from field access".into(),
            ))
        }
        ED::Pexp_apply(inner) => {
            // Call to an @comptime.inline function with comptime-known args:
            // compile body to JS, evaluate in Boa, return the result.
            let crate::parser::ast::PexpApply { funct, args, .. } = &**inner;
            let funct_expr = tctx.arena.get_expr(*funct);
            let func_name = match &*funct_expr.pexp_desc {
                ED::Pexp_ident(lid) => {
                    let longident = tctx.arena.get_longident(lid.txt);
                    tctx.arena.get_string(longident.last_idx()).to_string()
                }
                _ => {
                    return Err(super::TypeCoreError::Other(
                        "expected comptime string — complex calls not supported".into(),
                    ));
                }
            };
            let comptime_fn = tctx
                .comptime_functions
                .get(&func_name)
                .cloned()
                .ok_or_else(|| {
                    super::TypeCoreError::Other(format!(
                        "'{}' is not registered as @comptime or @comptime.inline",
                        func_name
                    ))
                })?;
            if !comptime_fn.is_inline {
                return Err(super::TypeCoreError::Other(format!(
                    "'{}' is not @comptime.inline — cannot evaluate at compile time",
                    func_name
                )));
            }

            // Resolve each argument as a comptime-known string/int/float/bool
            let arg_js_values: Vec<String> = args
                .iter()
                .map(|(_label, arg_idx)| -> TypeCoreResult<String> {
                    let arg_expr = tctx.arena.get_expr(*arg_idx);
                    // Try as a string first
                    if let Ok(s) = evaluate_comptime_string(tctx, arg_expr) {
                        return Ok(format!("{:?}", s));
                    }
                    // Fall back to translating as a simple JS expression
                    crate::types::comptime_inline::translate_simple_expr_to_js(arg_expr, tctx.arena)
                        .ok_or_else(|| {
                            super::TypeCoreError::Other(
                                "@comptime.inline arg could not be translated to JS".into(),
                            )
                        })
                })
                .collect::<Result<_, _>>()?;

            // Compile the function body to JS
            let body_expr = tctx.arena.get_expr(comptime_fn.body_expr_idx);
            let body_js =
                crate::types::comptime_inline::translate_simple_expr_to_js(body_expr, tctx.arena)
                    .ok_or_else(|| {
                    super::TypeCoreError::Other(format!(
                        "could not translate @comptime.inline body for '{}' to JS",
                        func_name
                    ))
                })?;

            // Build a JS program: apply the function expression to the args
            let program = format!("({})({})", body_js, arg_js_values.join(", "));

            match crate::types::comptime_inline::evaluate_js(&program) {
                crate::types::comptime_inline::InlineEvalResult::Value(
                    crate::types::comptime::ComptimeValue::String(s),
                ) => Ok(s),
                crate::types::comptime_inline::InlineEvalResult::Value(other) => {
                    Err(super::TypeCoreError::Other(format!(
                        "@comptime.inline '{}' returned non-string: {:?}",
                        func_name, other
                    )))
                }
                crate::types::comptime_inline::InlineEvalResult::Error(e) => {
                    Err(super::TypeCoreError::Other(format!(
                        "@comptime.inline '{}' evaluation failed: {}",
                        func_name, e
                    )))
                }
            }
        }
        _ => Err(super::TypeCoreError::Other(
            "expected comptime-known string".into(),
        )),
    }
}

fn capitalize_first(s: &str) -> String {
    let mut chars = s.chars();
    match chars.next() {
        Some(c) => c.to_uppercase().collect::<String>() + chars.as_str(),
        None => String::new(),
    }
}

/// Constructor name to match in a typeInfo switch (e.g., TypeInfo::Record → "Record").
fn constructor_name_of(ti: &crate::types::comptime::TypeInfo) -> &'static str {
    use crate::types::comptime::TypeInfo;
    match ti {
        TypeInfo::Int => "Int",
        TypeInfo::Float => "Float",
        TypeInfo::String => "String",
        TypeInfo::Bool => "Bool",
        TypeInfo::Unit => "Unit",
        TypeInfo::Char => "Char",
        TypeInfo::Bigint => "Bigint",
        TypeInfo::Record { .. } => "Record",
        TypeInfo::Variant { .. } => "Variant",
        TypeInfo::Array { .. } => "Array",
        TypeInfo::Option { .. } => "Option",
        TypeInfo::Function { .. } => "Function",
        TypeInfo::External { .. } => "External",
        TypeInfo::Opaque { .. } => "Opaque",
        TypeInfo::Tuple { .. } => "Tuple",
        TypeInfo::Unknown { .. } => "Unknown",
    }
}

/// Resolve @typeInfo(t) in a type-builder context.
fn resolve_typeinfo_in_builder(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    core_type: &crate::parser::ast::CoreType,
) -> TypeCoreResult<crate::types::comptime::TypeInfo> {
    // First check if the type arg is a comptime type binding (for generic @comptime type)
    if let crate::parser::ast::CoreTypeDesc::Ptyp_constr(inner) = &*core_type.ptyp_desc {
        let (ref lid, _) = **inner;
        let longident = tctx.arena.get_longident(lid.txt);
        let name = tctx.arena.get_string(longident.last_idx());
        if let Some(crate::types::comptime::ComptimeValue::Type(ti)) =
            tctx.comptime_bindings.get(name).cloned()
        {
            return Ok(ti);
        }
    }

    // Otherwise resolve as a normal type
    let ctx = tctx.type_ctx;
    ctx.begin_def();
    let resolved_ty = match transl_type(tctx, env, core_type) {
        Ok((_, ty)) => {
            ctx.end_def();
            ty
        }
        Err(e) => {
            ctx.end_def();
            return Err(e);
        }
    };
    Ok(crate::types::comptime::build_type_info(
        ctx,
        env,
        resolved_ty,
        &mut vec![],
    ))
}

/// Build a Texp_apply calling a generated monomorphized function.
fn make_comptime_call(
    tctx: &TypeCheckContext<'_>,
    gen_name: &str,
    runtime_args: &[Expression],
    expected_ty: TypeExprRef,
) -> Expression {
    let ctx = tctx.type_ctx;
    let func_ident = crate::ident::Ident::create_persistent(gen_name);
    let func_path = crate::types::Path::Pident(func_ident.clone());

    // Create Texp_ident for the generated function
    let func_type = if runtime_args.is_empty() {
        expected_ty
    } else {
        let arg_ty = runtime_args
            .first()
            .map_or(ctx.new_var(None), |a| a.exp_type);
        ctx.new_arrow_simple(arg_ty, expected_ty)
    };

    let func_vd = crate::types::ValueDescription {
        val_type: func_type,
        val_kind: crate::types::ValueKind::ValReg,
        val_loc: crate::location::Location::none(),
        val_attributes: vec![],
        val_path: Some(func_path.clone()),
    };

    // Texp_ident needs a Loc<LidentIdx> — use a zero index as placeholder
    let lid_loc = Located {
        txt: LidentIdx(0),
        loc: LocIdx(0),
    };

    let func_expr = Expression::new(
        ExpressionDesc::Texp_ident(func_path, lid_loc, func_vd),
        LocIdx(0),
        func_type,
        EnvRef(0),
        Attributes::new(),
    );

    if runtime_args.is_empty() {
        func_expr
    } else {
        let apply_args: Vec<_> = runtime_args
            .iter()
            .map(|arg| crate::types::typedtree::ApplyArg {
                label: crate::types::asttypes::ArgLabel::Nolabel,
                expression: Some(arg.clone()),
            })
            .collect();
        Expression::new(
            ExpressionDesc::Texp_apply {
                funct: Box::new(func_expr),
                args: apply_args,
                partial: false,
                transformed_jsx: false,
            },
            LocIdx(0),
            expected_ty,
            EnvRef(0),
            Attributes::new(),
        )
    }
}

/// Check if a typed expression contains a reference to a named identifier.
fn contains_ident_reference(expr: &Expression, name: &str) -> bool {
    match &expr.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => {
            matches!(path, crate::types::Path::Pident(id) if id.name() == name)
        }
        ExpressionDesc::Texp_apply { funct, args, .. } => {
            contains_ident_reference(funct, name)
                || args.iter().any(|a| {
                    a.expression
                        .as_ref()
                        .map_or(false, |e| contains_ident_reference(e, name))
                })
        }
        ExpressionDesc::Texp_let(_, bindings, body) => {
            bindings
                .iter()
                .any(|vb| contains_ident_reference(&vb.vb_expr, name))
                || contains_ident_reference(body, name)
        }
        ExpressionDesc::Texp_sequence(a, b) => {
            contains_ident_reference(a, name) || contains_ident_reference(b, name)
        }
        ExpressionDesc::Texp_record {
            fields,
            extended_expression,
        }
        | ExpressionDesc::Texp_record_sparse {
            fields,
            extended_expression,
            ..
        } => {
            fields.iter().any(|(_, _, def, _)| {
                if let super::typedtree::RecordLabelDefinition::Overridden(_, expr) = def {
                    contains_ident_reference(expr, name)
                } else {
                    false
                }
            }) || extended_expression
                .as_deref()
                .map_or(false, |expr| contains_ident_reference(expr, name))
        }
        _ => false, // Conservative: may miss some cases but safe
    }
}

/// Substitute all occurrences of a named identifier in a typed expression
/// with a replacement expression. Used to replace @comptime function
/// parameters with their actual arguments after type-checking.
fn substitute_ident(expr: &mut Expression, name: &str, replacement: &Expression) {
    match &mut expr.exp_desc {
        ExpressionDesc::Texp_ident(path, _, _) => {
            if path.name() == name {
                *expr = replacement.clone();
            }
        }
        ExpressionDesc::Texp_let(_, bindings, body) => {
            for vb in bindings {
                substitute_ident(&mut vb.vb_expr, name, replacement);
            }
            substitute_ident(body, name, replacement);
        }
        ExpressionDesc::Texp_apply { funct, args, .. } => {
            substitute_ident(funct, name, replacement);
            for arg in args {
                if let Some(ref mut e) = arg.expression {
                    substitute_ident(e, name, replacement);
                }
            }
        }
        ExpressionDesc::Texp_sequence(e1, e2) => {
            substitute_ident(e1, name, replacement);
            substitute_ident(e2, name, replacement);
        }
        ExpressionDesc::Texp_ifthenelse(cond, then_, else_) => {
            substitute_ident(cond, name, replacement);
            substitute_ident(then_, name, replacement);
            if let Some(e) = else_ {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_field(base, _, _) => {
            substitute_ident(base, name, replacement);
        }
        ExpressionDesc::Texp_tuple(elems) => {
            for e in elems {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_array(elems) => {
            for e in elems {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_construct(_, _, args) => {
            for e in args {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_record {
            fields,
            extended_expression,
        } => {
            for (_, _, def, _) in fields {
                if let super::typedtree::RecordLabelDefinition::Overridden(_, e) = def {
                    substitute_ident(e, name, replacement);
                }
            }
            if let Some(e) = extended_expression {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_record_sparse {
            fields,
            extended_expression,
            ..
        } => {
            for (_, _, def, _) in fields {
                if let super::typedtree::RecordLabelDefinition::Overridden(_, e) = def {
                    substitute_ident(e, name, replacement);
                }
            }
            if let Some(e) = extended_expression {
                substitute_ident(e, name, replacement);
            }
        }
        ExpressionDesc::Texp_match(scrutinee, cases, exc_cases, _) => {
            substitute_ident(scrutinee, name, replacement);
            for case in cases {
                substitute_ident(&mut case.c_rhs, name, replacement);
            }
            for case in exc_cases {
                substitute_ident(&mut case.c_rhs, name, replacement);
            }
        }
        _ => {}
    }
}

/// Extract parameter info and innermost body from a function parse tree.
/// Handles both `Pexp_fun` (value params) and `Pexp_newtype` (type params).
fn extract_function_params_and_body<'a>(
    expr: &'a ParsedExpression,
    arena: &'a crate::parse_arena::ParseArena,
) -> (Vec<crate::types::comptime::ComptimeParam>, ParsedExpression) {
    let mut params = Vec::new();
    let mut current = expr;

    loop {
        match &*current.pexp_desc {
            crate::parser::ast::ExpressionDesc::Pexp_fun(inner) => {
                // Current Parsetree stores locally abstract types and the full
                // source parameter list on the n-ary function node. This is
                // the same binder order consumed by type_function_nary_with_newtypes.
                for (name_loc, _) in arena.nary_fun_newtypes(inner) {
                    params.push(crate::types::comptime::ComptimeParam {
                        name: arena.get_string(name_loc.txt).to_string(),
                        is_comptime: true,
                        is_type: true,
                    });
                }
                for param in arena.nary_fun_params(inner).iter() {
                    let pat = arena.get_pat(param.p_pat);
                    let name = match &*pat.ppat_desc {
                        crate::parser::ast::PatternDesc::Ppat_var(name_loc) => {
                            Some(arena.get_string(name_loc.txt).to_string())
                        }
                        crate::parser::ast::PatternDesc::Ppat_constraint(inner_box) => {
                            let (inner_pat_idx, _) = &**inner_box;
                            let inner_pat = arena.get_pat(*inner_pat_idx);
                            if let crate::parser::ast::PatternDesc::Ppat_var(name_loc) =
                                &*inner_pat.ppat_desc
                            {
                                Some(arena.get_string(name_loc.txt).to_string())
                            } else {
                                None
                            }
                        }
                        _ => None,
                    };
                    if let Some(name) = name {
                        params.push(crate::types::comptime::ComptimeParam {
                            name,
                            is_comptime: false,
                            is_type: false,
                        });
                    }
                }
                current = arena.get_expr(arena.nary_fun_body(inner));
            }
            crate::parser::ast::ExpressionDesc::Pexp_newtype(inner) => {
                // Frozen-v0 PPX trees retain nested Pexp_newtype wrappers.
                let (ref name_loc, ref body_idx) = **inner;
                let name = arena.get_string(name_loc.txt).to_string();
                params.push(crate::types::comptime::ComptimeParam {
                    name,
                    is_comptime: true,
                    is_type: true,
                });
                current = arena.get_expr(*body_idx);
            }
            _ => return (params, current.clone()),
        }
    }
}

/// Extract the innermost body expression from a function parse tree.
/// Unwraps (x) => (y) => body → body.
fn extract_function_body<'a>(
    expr: &'a ParsedExpression,
    arena: &'a crate::parse_arena::ParseArena,
) -> ParsedExpression {
    match &*expr.pexp_desc {
        crate::parser::ast::ExpressionDesc::Pexp_fun(inner) => {
            let body = arena.get_expr(inner.rhs);
            extract_function_body(body, arena)
        }
        _ => expr.clone(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::context::IdGenerator;
    use std::borrow::Cow;

    #[test]
    fn value_usage_marks_all_declarations_with_the_same_key() {
        let type_ctx = TypeContext::new(std::sync::Arc::new(IdGenerator::new()));
        let arena = ParseArena::new();
        let mut tctx = TypeCheckContext::new(&type_ctx, &arena);
        let val_loc = Location::none();
        for _ in 0..2 {
            tctx.value_usage_checks.push(ValueUsageCheck {
                name: "x".to_string(),
                val_loc,
                warning_loc: LocIdx::none(),
                warning: Warning::UnusedArgument,
                is_error: false,
                used: false,
                seq: 0,
            });
        }

        tctx.mark_value_used("x", val_loc);

        assert!(tctx.value_usage_checks.iter().all(|check| check.used));
    }

    #[test]
    fn test_convert_constant_int() {
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("42"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert_eq!(result, Constant::Int(42));
    }

    #[test]
    fn test_convert_constant_large_fits_63bit() {
        // Values that fit in 63-bit should be preserved
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("99999999999999999"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert_eq!(result, Constant::Int(99999999999999999));
    }

    #[test]
    fn test_convert_constant_overflow_too_large() {
        // Values that don't fit in i64 should still error
        let cst =
            crate::parser::ast::Constant::Integer(Cow::Borrowed("99999999999999999999999"), None);
        let result = convert_constant(&cst, LocIdx(0));
        assert!(matches!(result, Err(TypeCoreError::LiteralOverflow { .. })));
    }

    #[test]
    fn test_convert_constant_underscores() {
        // 949460645006 fits in 63 bits, should be preserved
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("949_460_645_006"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert_eq!(result, Constant::Int(949_460_645_006));
    }

    #[test]
    fn test_convert_constant_hex() {
        // 0xFFFFFFFF = 4294967295, fits in 63 bits
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("0xffff_ffff"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert_eq!(result, Constant::Int(4294967295));
    }

    #[test]
    fn test_convert_constant_63bit_wrap() {
        // 4611686018427387904 = 2^62, wraps to -2^62 in 63-bit
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("4611686018427387904"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert_eq!(result, Constant::Int(-4611686018427387904));
    }

    #[test]
    fn test_convert_constant_string() {
        let cst = crate::parser::ast::Constant::String(Cow::Borrowed("hello"), None);
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert!(matches!(result, Constant::String(s, None) if s == "hello"));
    }

    #[test]
    fn test_convert_constant_bigint() {
        let cst = crate::parser::ast::Constant::Integer(Cow::Borrowed("12345"), Some('n'));
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert!(matches!(result, Constant::BigInt(true, d) if d == "12345"));
    }

    #[test]
    fn test_convert_constant_bigint_removes_underscores() {
        let cst =
            crate::parser::ast::Constant::Integer(Cow::Owned("01_000_000".to_string()), Some('n'));
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert!(matches!(result, Constant::BigInt(true, d) if d == "1000000"));
    }

    #[test]
    fn test_convert_constant_bigint_preserves_non_decimal_heads() {
        let cst = crate::parser::ast::Constant::Integer(
            Cow::Owned("00x1_000_000".to_string()),
            Some('n'),
        );
        let result = convert_constant(&cst, LocIdx(0)).unwrap();
        assert!(matches!(result, Constant::BigInt(true, d) if d == "00x1000000"));
    }

    #[test]
    fn test_type_constant() {
        let id_gen = IdGenerator::new();
        let ctx = TypeContext::new(std::sync::Arc::new(id_gen));
        let env = crate::types::initial_env(&ctx);

        let cst = Constant::Int(42);
        let ty = type_constant(&ctx, &env, &cst);
        // Check that we got a valid type (can get its description)
        let desc = ctx.get_desc(ty);
        assert!(matches!(&*desc, crate::types::TypeDesc::Tconstr { .. }));
    }

    #[test]
    fn test_pattern_state_enter_variable() {
        let id_gen = IdGenerator::new();
        let ctx = TypeContext::new(std::sync::Arc::new(id_gen));
        let _env = crate::types::initial_env(&ctx);
        let mut state = PatternState::new();

        let mut arena = ParseArena::new();
        let loc = LocIdx::none();
        let ty = ctx.new_var(None);
        let x_idx = arena.intern("x");
        let name = Located { txt: x_idx, loc };

        let id = state.enter_variable(&ctx, loc, &name, ty, false, false, &arena);
        assert!(id.is_ok());

        // Duplicate should fail
        let id2 = state.enter_variable(&ctx, loc, &name, ty, false, false, &arena);
        assert!(matches!(
            id2,
            Err(TypeCoreError::MultiplyBoundVariable { .. })
        ));
    }

    #[test]
    fn test_type_pattern_or_reuses_left_branch_ident() {
        let id_gen = IdGenerator::new();
        let ctx = TypeContext::new(std::sync::Arc::new(id_gen));
        let env = crate::types::initial_env(&ctx);
        let mut arena = ParseArena::new();

        let loc = LocIdx::none();
        let x_idx = arena.intern("x");
        let x_name = Located { txt: x_idx, loc };
        let left = arena.push_pat(crate::parser::ast::Pattern {
            ppat_desc: Box::new(crate::parser::ast::PatternDesc::Ppat_var(x_name.clone())),
            ppat_loc: loc,
            ppat_attributes: Attributes::new(),
        });
        let right = arena.push_pat(crate::parser::ast::Pattern {
            ppat_desc: Box::new(crate::parser::ast::PatternDesc::Ppat_var(x_name)),
            ppat_loc: loc,
            ppat_attributes: Attributes::new(),
        });
        let or_pat = crate::parser::ast::Pattern {
            ppat_desc: Box::new(crate::parser::ast::PatternDesc::Ppat_or(left, right)),
            ppat_loc: loc,
            ppat_attributes: Attributes::new(),
        };
        let mut tctx = TypeCheckContext::new(&ctx, &arena);
        let mut state = PatternState::new();

        let typed_pat = type_pattern(
            &mut tctx,
            &env,
            &or_pat,
            env.type_int(&ctx),
            PatternMode::Normal,
            &mut state,
        )
        .expect("or-pattern should type-check");

        let crate::types::typedtree::PatternDesc::Tpat_or(left_pat, right_pat, None) =
            typed_pat.pat_desc
        else {
            panic!("expected typed or-pattern");
        };
        let crate::types::typedtree::PatternDesc::Tpat_var(left_id, _) = &left_pat.pat_desc else {
            panic!("expected left branch variable");
        };
        let crate::types::typedtree::PatternDesc::Tpat_var(right_id, _) = &right_pat.pat_desc
        else {
            panic!("expected right branch variable");
        };

        assert_eq!(state.pattern_variables.len(), 1);
        assert!(left_id.same(right_id));
        assert!(state.pattern_variables[0].id.same(left_id));
    }

    #[test]
    fn test_type_check_context_creation() {
        let id_gen = IdGenerator::new();
        let ctx = TypeContext::new(std::sync::Arc::new(id_gen));
        let arena = ParseArena::new();
        let tctx = TypeCheckContext::new(&ctx, &arena);

        assert!(tctx.newtype_level.is_none());
        assert!(tctx.diagnostics.is_empty());
    }

    #[test]
    fn test_env_type_constructors() {
        let id_gen = IdGenerator::new();
        let ctx = TypeContext::new(std::sync::Arc::new(id_gen));
        let env = crate::types::initial_env(&ctx);

        let int_ty = env.type_int(&ctx);
        let bool_ty = env.type_bool(&ctx);
        let string_ty = env.type_string(&ctx);

        // All should be valid Tconstr types
        assert!(matches!(
            &*ctx.get_desc(int_ty),
            crate::types::TypeDesc::Tconstr { .. }
        ));
        assert!(matches!(
            &*ctx.get_desc(bool_ty),
            crate::types::TypeDesc::Tconstr { .. }
        ));
        assert!(matches!(
            &*ctx.get_desc(string_ty),
            crate::types::TypeDesc::Tconstr { .. }
        ));

        // Array type with element type
        let elem_ty = ctx.new_var(None);
        let array_ty = env.type_array(&ctx, elem_ty);
        assert!(matches!(
            &*ctx.get_desc(array_ty),
            crate::types::TypeDesc::Tconstr { .. }
        ));
    }

    #[test]
    fn test_ocaml_hashtbl_hash_string_matches_ocaml() {
        assert_eq!(ocaml_hashtbl_hash_string("_self"), 448_023_825);
        assert_eq!(ocaml_hashtbl_hash_string("_blank"), 482_879_870);
        assert_eq!(ocaml_hashtbl_hash_string("_parent"), 914_286_090);
        assert_eq!(ocaml_hashtbl_hash_string("_top"), 861_764_747);
        assert_eq!(ocaml_hashtbl_hash_string("foo"), 763_646_369);
        assert_eq!(ocaml_hashtbl_hash_string("Some"), 26_923_831);
    }

    #[test]
    fn test_ocaml_hashtbl_fold_order_matches_ocaml() {
        let labels = vec![
            "_self".to_string(),
            "_blank".to_string(),
            "_parent".to_string(),
            "_top".to_string(),
        ];
        assert_eq!(
            ocaml_hashtbl_fold_order(&labels),
            vec![
                "_parent".to_string(),
                "_top".to_string(),
                "_self".to_string(),
                "_blank".to_string()
            ]
        );
    }

    #[test]
    fn test_ocaml_hashtbl_fold_order_pair_int_string() {
        // bs_unwrap_test: [#Pair(string, int) | #Int(int) | #String(string)]
        // OCaml output order: Pair, String, Int
        let labels = vec!["Pair".to_string(), "Int".to_string(), "String".to_string()];
        let result = ocaml_hashtbl_fold_order(&labels);
        assert_eq!(
            result,
            vec!["Pair".to_string(), "String".to_string(), "Int".to_string(),]
        );
    }
}

// ============================================================================
// Parmatch bridge (typecore.ml:1741-1776, pattern_printer.ml)
// ============================================================================

/// The type checker side of [`crate::types::parmatch::Oracle`].
struct TypecoreParmatchOracle<'t, 'c> {
    tctx: &'t mut TypeCheckContext<'c>,
    env: &'t Env,
    /// `expected_ty` passed to `partial_pred`.
    expected_ty: TypeExprRef,
    /// `~lev` passed to `partial_pred`.
    level: i32,
    /// `~explode` for `check_partial` (typecore.ml:1763-1767).
    partial_explode: i32,
    none_type: Option<TypeExprRef>,
}

fn parmatch_warning(warning: &crate::types::parmatch::ParmatchWarning) -> Warning {
    use crate::types::parmatch::ParmatchWarning as W;
    match warning {
        W::AllClausesGuarded => Warning::AllClausesGuarded,
        W::PartialMatch(example) => Warning::PartialMatch {
            example: example.clone(),
        },
        W::FragileMatch(typ) => Warning::FragileMatch { typ: typ.clone() },
        W::UnusedMatch => Warning::UnusedMatch,
        W::UnusedPat => Warning::UnusedPat,
        W::UnreachableCase => Warning::UnreachableCase,
        W::AmbiguousPattern(vars) => Warning::AmbiguousPattern { vars: vars.clone() },
    }
}

type PersistentEnvSlot = Option<crate::cmi::persistent_env::PersistentEnv>;

/// `get_variant_constructors env ty` (parmatch.ml:490-501).
fn pm_variant_constructors(
    ctx: &TypeContext,
    env: &Env,
    pers: &mut PersistentEnvSlot,
    ty: TypeExprRef,
) -> Vec<crate::types::ConstructorDescription> {
    let mut ty = ctx.repr(ty);
    loop {
        let path = match &*ctx.get_desc(ty) {
            TypeDesc::Tconstr { path, .. } => path.clone(),
            _ => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
        };
        let Some(decl) = lookup_type_decl_for_path(&path, env, pers, ctx) else {
            crate::misc::fatal_error("Parmatch.get_variant_constructors")
        };
        match &decl.type_kind {
            crate::types::TypeKind::TypeVariant(..) => {
                return crate::types::env_lazy::constructors_of_type_path(&path, &decl, ctx);
            }
            _ if decl.type_manifest.is_some() => {
                match crate::types::ctype::expand_head_once(ctx, env, ty) {
                    Some(expanded) => ty = expanded,
                    None => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
                }
            }
            _ => crate::misc::fatal_error("Parmatch.get_variant_constructors"),
        }
    }
}

/// `lbl.lbl_all` for labels whose result type is `record_ty`.
fn pm_record_labels(
    ctx: &TypeContext,
    env: &Env,
    pers: &mut PersistentEnvSlot,
    record_ty: TypeExprRef,
) -> Vec<crate::types::LabelDescription> {
    let ty = ctx.repr(record_ty);
    let path = match &*ctx.get_desc(ty) {
        TypeDesc::Tconstr { path, .. } => path.clone(),
        _ => return Vec::new(),
    };
    match lookup_type_decl_for_path(&path, env, pers, ctx) {
        Some(decl) => crate::types::env_lazy::labels_of_type_path(&path, &decl, ctx),
        None => Vec::new(),
    }
}

/// The environment part of `pats_of_type` (parmatch.ml:942-966).
fn pm_type_shape(
    ctx: &TypeContext,
    env: &Env,
    pers: &mut PersistentEnvSlot,
    ty: TypeExprRef,
    always: bool,
) -> crate::types::parmatch::TypeShape {
    use crate::types::parmatch::TypeShape;
    let expanded = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    let path = match &*ctx.get_desc(expanded) {
        TypeDesc::Tconstr { path, .. } => path.clone(),
        TypeDesc::Ttuple(items) => return TypeShape::Tuple(items.len()),
        _ => return TypeShape::Other,
    };
    let Some(decl) = lookup_type_decl_for_path(&path, env, pers, ctx) else {
        return TypeShape::Other;
    };
    match &decl.type_kind {
        crate::types::TypeKind::TypeVariant(cl, _)
            if always || cl.len() == 1 || cl.iter().all(|cd| cd.cd_res.is_some()) =>
        {
            TypeShape::Variant(crate::types::env_lazy::constructors_of_type_path(&path, &decl, ctx))
        }
        crate::types::TypeKind::TypeRecord(..) => {
            TypeShape::Record(crate::types::env_lazy::labels_of_type_path(&path, &decl, ctx))
        }
        _ => TypeShape::Other,
    }
}

fn pm_is_predef_some_lid(arena: &ParseArena, lid: LidentIdx) -> bool {
    match arena.get_longident(lid) {
        Longident::Ldot(prefix, name) => {
            arena.get_string(*name) == "Some"
                && matches!(prefix.as_ref(), Longident::Lident(p) if arena.get_string(*p) == "*predef*")
        }
        _ => false,
    }
}

fn pm_is_block_that_cannot_be_undefined(
    ctx: &TypeContext,
    cstr: &crate::types::ConstructorDescription,
) -> bool {
    use crate::types::variant_runtime::{BlockType, ConstructorCase};
    let crate::types::ConstructorKind::Ordinary(reference) = cstr.cstr_kind else {
        return false;
    };
    match reference.representation(ctx) {
        // Ast_untagged_variants.block_type_can_be_undefined
        // (ast_untagged_variants.ml:89-93).
        ConstructorCase::Block(block) => {
            matches!(block.block_type, Some(ref block_type) if *block_type != BlockType::Unknown)
        }
        ConstructorCase::Constant(_) => false,
    }
}

fn pm_variant_length(ctx: &TypeContext, cstr: &crate::types::ConstructorDescription) -> usize {
    match cstr.cstr_kind {
        crate::types::ConstructorKind::Ordinary(reference) => {
            ctx.with_variant_layout(reference.variant, |layout| layout.constructors.len())
        }
        crate::types::ConstructorKind::Extension(_) => 0,
    }
}

/// `get_type_path ty tenv` (parmatch.ml:334-338).
fn pm_type_path(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> Path {
    let ty = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    match &*ctx.get_desc(ty) {
        TypeDesc::Tconstr { path, .. } => path.clone(),
        _ => crate::misc::fatal_error("Parmatch.get_type_path"),
    }
}

/// `row_of_pat` (parmatch.ml:850-853).
fn pm_row_of(ctx: &TypeContext, env: &Env, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
    let ty = ctx.repr(crate::types::ctype::expand_head(ctx, env, ty));
    match &*ctx.get_desc(ty) {
        TypeDesc::Tvariant(row) => crate::types::btype::row_repr(ctx, row),
        _ => crate::misc::fatal_error("Parmatch.row_of_pat"),
    }
}

fn pm_has_dict_pattern_attribute(arena: &ParseArena, pat: &Pattern) -> bool {
    pat.pat_attributes
        .iter()
        .any(|attr| arena.get_string(attr.0.txt) == DICT_PATTERN_ATTRIBUTE)
}

impl crate::types::parmatch::Oracle for TypecoreParmatchOracle<'_, '_> {
    fn ctx(&self) -> &TypeContext {
        self.tctx.type_ctx
    }

    fn expand_head(&mut self, _env: EnvRef, ty: TypeExprRef) -> TypeExprRef {
        let ctx = self.tctx.type_ctx;
        ctx.repr(crate::types::ctype::expand_head(ctx, self.env, ty))
    }

    fn variant_constructors(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
    ) -> Vec<crate::types::ConstructorDescription> {
        pm_variant_constructors(self.tctx.type_ctx, self.env, &mut self.tctx.persistent_env, ty)
    }

    fn record_labels(
        &mut self,
        _env: EnvRef,
        record_ty: TypeExprRef,
    ) -> Vec<crate::types::LabelDescription> {
        pm_record_labels(
            self.tctx.type_ctx,
            self.env,
            &mut self.tctx.persistent_env,
            record_ty,
        )
    }

    fn type_shape(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
        always: bool,
    ) -> crate::types::parmatch::TypeShape {
        pm_type_shape(
            self.tctx.type_ctx,
            self.env,
            &mut self.tctx.persistent_env,
            ty,
            always,
        )
    }

    fn create_ident(&mut self, name: &str) -> Ident {
        self.tctx.type_ctx.create_ident(name)
    }

    fn close_variant(&mut self, _env: EnvRef, _pat_env: EnvRef, ty: TypeExprRef) {
        pressure_matrix_close_variant_type(self.tctx, self.env, ty);
    }

    fn warn(&mut self, loc: LocIdx, warning: crate::types::parmatch::ParmatchWarning) {
        self.tctx.report_warning(loc, parmatch_warning(&warning));
    }

    fn is_active(&self, warning: &crate::types::parmatch::ParmatchWarning) -> bool {
        self.tctx
            .warning_config
            .is_active(&parmatch_warning(warning))
    }

    fn is_ghost(&self, loc: LocIdx) -> bool {
        self.tctx.arena.loc_ghost(loc)
    }

    fn print_pattern(&mut self, v: &Pattern) -> String {
        print_counter_example(self.tctx.arena, v)
    }

    fn pred(
        &mut self,
        kind: crate::types::parmatch::PredKind,
        u: Pattern,
        loc: Option<LocIdx>,
    ) -> Option<Pattern> {
        let (mode, explode) = match kind {
            crate::types::parmatch::PredKind::Partial => {
                (PatternMode::Normal, self.partial_explode)
            }
            crate::types::parmatch::PredKind::Unused => (PatternMode::SplitOr, 5),
        };
        partial_pred(
            self.tctx,
            self.env,
            self.level,
            mode,
            explode,
            self.expected_ty,
            &u,
            loc,
        )
    }

    fn is_non_extendable_predef_path(&self, path: &Path) -> bool {
        !extendable_fragile_match_path(path)
    }

    fn placeholder_lid(&self) -> LidentIdx {
        self.tctx.arena.push_typecheck_lident("?temp?")
    }

    fn none_type(&mut self) -> TypeExprRef {
        let ctx = self.tctx.type_ctx;
        *self
            .none_type
            .get_or_insert_with(|| ctx.new_type(TypeDesc::Ttuple(Vec::new())))
    }

    fn has_dict_pattern_attribute(&self, pat: &Pattern) -> bool {
        pm_has_dict_pattern_attribute(self.tctx.arena, pat)
    }

    fn is_pat_from_variant_spread(&self, pat: &Pattern) -> bool {
        pattern_from_variant_spread_attr(self.tctx.arena, pat)
    }

    fn is_predef_some_lid(&self, lid: LidentIdx) -> bool {
        pm_is_predef_some_lid(self.tctx.arena, lid)
    }

    fn is_block_that_cannot_be_undefined(&self, cstr: &crate::types::ConstructorDescription) -> bool {
        pm_is_block_that_cannot_be_undefined(self.tctx.type_ctx, cstr)
    }

    fn variant_length(&self, cstr: &crate::types::ConstructorDescription) -> usize {
        pm_variant_length(self.tctx.type_ctx, cstr)
    }

    fn type_path(&mut self, _env: EnvRef, ty: TypeExprRef) -> Path {
        pm_type_path(self.tctx.type_ctx, self.env, ty)
    }

    fn row_of(&mut self, _env: EnvRef, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
        pm_row_of(self.tctx.type_ctx, self.env, ty)
    }
}

/// A Parmatch oracle for the translation phase, where only the
/// environment queries of `le_pat`/`satisfiable` are needed
/// (translmod.ml:391 `Parmatch.irrefutable`).
struct TranslParmatchOracle<'t> {
    ctx: &'t TypeContext,
    arena: &'t ParseArena,
    env: &'t Env,
    persistent_env: &'t mut PersistentEnvSlot,
    none_type: Option<TypeExprRef>,
}

impl crate::types::parmatch::Oracle for TranslParmatchOracle<'_> {
    fn ctx(&self) -> &TypeContext {
        self.ctx
    }

    fn expand_head(&mut self, _env: EnvRef, ty: TypeExprRef) -> TypeExprRef {
        self.ctx.repr(crate::types::ctype::expand_head(self.ctx, self.env, ty))
    }

    fn variant_constructors(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
    ) -> Vec<crate::types::ConstructorDescription> {
        pm_variant_constructors(self.ctx, self.env, self.persistent_env, ty)
    }

    fn record_labels(
        &mut self,
        _env: EnvRef,
        record_ty: TypeExprRef,
    ) -> Vec<crate::types::LabelDescription> {
        pm_record_labels(self.ctx, self.env, self.persistent_env, record_ty)
    }

    fn type_shape(
        &mut self,
        _env: EnvRef,
        ty: TypeExprRef,
        always: bool,
    ) -> crate::types::parmatch::TypeShape {
        pm_type_shape(self.ctx, self.env, self.persistent_env, ty, always)
    }

    fn create_ident(&mut self, name: &str) -> Ident {
        self.ctx.create_ident(name)
    }

    fn close_variant(&mut self, _env: EnvRef, _pat_env: EnvRef, _ty: TypeExprRef) {
        crate::misc::fatal_error("Parmatch.close_variant during translation")
    }

    fn warn(&mut self, _loc: LocIdx, _warning: crate::types::parmatch::ParmatchWarning) {}

    fn is_active(&self, _warning: &crate::types::parmatch::ParmatchWarning) -> bool {
        false
    }

    fn is_ghost(&self, loc: LocIdx) -> bool {
        self.arena.loc_ghost(loc)
    }

    fn print_pattern(&mut self, v: &Pattern) -> String {
        print_counter_example(self.arena, v)
    }

    fn pred(
        &mut self,
        _kind: crate::types::parmatch::PredKind,
        u: Pattern,
        _loc: Option<LocIdx>,
    ) -> Option<Pattern> {
        Some(u)
    }

    fn is_non_extendable_predef_path(&self, path: &Path) -> bool {
        !extendable_fragile_match_path(path)
    }

    fn placeholder_lid(&self) -> LidentIdx {
        self.arena.push_typecheck_lident("?temp?")
    }

    fn none_type(&mut self) -> TypeExprRef {
        let ctx = self.ctx;
        *self
            .none_type
            .get_or_insert_with(|| ctx.new_type(TypeDesc::Ttuple(Vec::new())))
    }

    fn has_dict_pattern_attribute(&self, pat: &Pattern) -> bool {
        pm_has_dict_pattern_attribute(self.arena, pat)
    }

    fn is_pat_from_variant_spread(&self, pat: &Pattern) -> bool {
        pattern_from_variant_spread_attr(self.arena, pat)
    }

    fn is_predef_some_lid(&self, lid: LidentIdx) -> bool {
        pm_is_predef_some_lid(self.arena, lid)
    }

    fn is_block_that_cannot_be_undefined(&self, cstr: &crate::types::ConstructorDescription) -> bool {
        pm_is_block_that_cannot_be_undefined(self.ctx, cstr)
    }

    fn variant_length(&self, cstr: &crate::types::ConstructorDescription) -> usize {
        pm_variant_length(self.ctx, cstr)
    }

    fn type_path(&mut self, _env: EnvRef, ty: TypeExprRef) -> Path {
        pm_type_path(self.ctx, self.env, ty)
    }

    fn row_of(&mut self, _env: EnvRef, ty: TypeExprRef) -> crate::types::type_expr::RowDesc {
        pm_row_of(self.ctx, self.env, ty)
    }
}

/// `Parmatch.irrefutable pat` (parmatch.ml:2260), as used by translmod.ml:391.
pub(crate) fn parmatch_irrefutable(
    ctx: &TypeContext,
    arena: &ParseArena,
    env: &Env,
    persistent_env: &mut PersistentEnvSlot,
    pat: &Pattern,
) -> bool {
    let oracle = TranslParmatchOracle {
        ctx,
        arena,
        env,
        persistent_env,
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle);
    pm.irrefutable(pat)
}

/// `partial_pred ~lev ?mode ?explode env expected_ty constrs labels p`
/// (typecore.ml:1743-1759) applied to `Conv.conv u` (parmatch.ml:1961-2001).
#[allow(clippy::too_many_arguments)]
fn partial_pred(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    level: i32,
    mode: PatternMode,
    explode: i32,
    expected_ty: TypeExprRef,
    u: &Pattern,
    loc: Option<LocIdx>,
) -> Option<Pattern> {
    let ctx = tctx.type_ctx;
    let old_constructors = std::mem::take(&mut tctx.generated_pattern_constructors);
    let old_labels = std::mem::take(&mut tctx.generated_pattern_labels);
    let parsed = conv_counter_example(tctx, u, loc);
    let type_snapshot = ctx.snapshot_type_state();
    let unify_snapshot = tctx.unify_state.snapshot_backtrack_state();
    let diagnostic_len = tctx.diagnostics.len();
    let mut state = PatternState::new();
    // Ctype.with_passive_variants (ctype.ml:2061-2072).
    let passive = ctx.set_passive_variants(true);
    let result = type_pattern_with_existentials_at_level(
        tctx,
        env,
        tctx.arena.get_pat(parsed),
        expected_ty,
        mode,
        true,
        &mut state,
        level,
        explode,
    );
    ctx.set_passive_variants(passive);
    ctx.restore_type_state(type_snapshot);
    tctx.unify_state.restore_backtrack_state(unify_snapshot);
    tctx.diagnostics.truncate(diagnostic_len);
    tctx.generated_pattern_constructors = old_constructors;
    tctx.generated_pattern_labels = old_labels;
    result.ok()
}

fn untype_constant(constant: &Constant) -> ParsedConstant {
    // Untypeast.constant (untypeast.ml:19-27).
    match constant {
        Constant::Int(value) => ParsedConstant::Integer(value.to_string().into(), None),
        Constant::Char(value) => ParsedConstant::Char(*value),
        Constant::String(value, delimiter) => {
            ParsedConstant::String(value.clone().into(), delimiter.clone().map(Into::into))
        }
        Constant::Float(value) => ParsedConstant::Float(value.clone().into(), None),
        Constant::BigInt(positive, digits) => {
            let value = if *positive {
                digits.clone()
            } else {
                format!("-{digits}")
            };
            ParsedConstant::Integer(value.into(), Some('n'))
        }
    }
}

fn push_parsed_pattern(
    arena: &ParseArena,
    loc: LocIdx,
    desc: crate::parser::ast::PatternDesc,
) -> crate::parse_arena::PatIdx {
    arena.push_typecheck_pattern(ParsedPattern {
        ppat_desc: Box::new(desc),
        ppat_loc: loc,
        ppat_attributes: Attributes::new(),
    })
}

/// `Conv.conv` (parmatch.ml:1961-2001): the counter-example as a parsetree
/// pattern whose constructors and labels are the fresh `#$name<n>` entries of
/// `generated_pattern_constructors`/`generated_pattern_labels`.
fn conv_counter_example(
    tctx: &mut TypeCheckContext<'_>,
    typed: &Pattern,
    top_loc: Option<LocIdx>,
) -> crate::parse_arena::PatIdx {
    use crate::parser::ast::{PatternDesc as P, PatternRecordField};

    fn fresh(counter: &mut u32, name: &str) -> String {
        let current = *counter;
        *counter += 1;
        format!("#${name}{current}")
    }

    fn lp(
        tctx: &mut TypeCheckContext<'_>,
        pat: &Pattern,
        counter: &mut u32,
        loc: LocIdx,
    ) -> crate::parse_arena::PatIdx {
        let arena = tctx.arena;
        let none = LocIdx::none();
        match &pat.pat_desc {
            PatternDesc::Tpat_or(left, right, _) => {
                let left = lp(tctx, left, counter, none);
                let right = lp(tctx, right, counter, none);
                push_parsed_pattern(arena, loc, P::Ppat_or(left, right))
            }
            PatternDesc::Tpat_var(_, name) if name.txt == "*extension*" => {
                let txt = arena.push_typecheck_string(name.txt.clone());
                push_parsed_pattern(arena, loc, P::Ppat_var(Located::new(txt, name.loc)))
            }
            PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) => {
                push_parsed_pattern(arena, loc, P::Ppat_any)
            }
            PatternDesc::Tpat_constant(constant) => push_parsed_pattern(
                arena,
                loc,
                P::Ppat_constant(Box::new(untype_constant(constant))),
            ),
            PatternDesc::Tpat_alias(inner, _, _) => lp(tctx, inner, counter, loc),
            PatternDesc::Tpat_tuple(items) => {
                let items = items.iter().map(|item| lp(tctx, item, counter, none)).collect();
                push_parsed_pattern(arena, loc, P::Ppat_tuple(Box::new(items)))
            }
            PatternDesc::Tpat_construct(cstr_lid, cstr, args) => {
                let id = fresh(counter, &cstr.cstr_name);
                tctx.generated_pattern_constructors
                    .push((id.clone(), cstr.clone()));
                let lid = Located::new(arena.push_typecheck_lident(&id), cstr_lid.loc);
                let mut items: Vec<_> = args.iter().map(|arg| lp(tctx, arg, counter, none)).collect();
                let arg = match items.len() {
                    0 => None,
                    1 => items.pop(),
                    _ => Some(push_parsed_pattern(arena, none, P::Ppat_tuple(Box::new(items)))),
                };
                push_parsed_pattern(arena, loc, P::Ppat_construct(lid, arg))
            }
            PatternDesc::Tpat_variant(label, arg, _) => {
                let arg = arg.as_deref().map(|arg| lp(tctx, arg, counter, none));
                push_parsed_pattern(
                    arena,
                    loc,
                    P::Ppat_variant(Box::new((label.clone().into(), arg))),
                )
            }
            PatternDesc::Tpat_record(fields, _, _) => {
                let fields = fields
                    .iter()
                    .map(|(_, lbl, p, optional)| {
                        let id = fresh(counter, &lbl.lbl_name);
                        tctx.generated_pattern_labels.push((id.clone(), lbl.clone()));
                        PatternRecordField {
                            lid: Located::new(arena.push_typecheck_lident(&id), none),
                            pat: lp(tctx, p, counter, none),
                            opt: *optional,
                        }
                    })
                    .collect();
                // TODO: Conv.conv_record_rest (parmatch.ml:1948-1959) keeps the
                // rest binding with a `Typ.constr` annotation.
                push_parsed_pattern(
                    arena,
                    loc,
                    P::Ppat_record(Box::new((fields, crate::parser::ast::ClosedFlag::Open, None))),
                )
            }
            PatternDesc::Tpat_array(items) => {
                let items = items.iter().map(|item| lp(tctx, item, counter, none)).collect();
                push_parsed_pattern(arena, loc, P::Ppat_array(Box::new(items)))
            }
        }
    }

    // `Conv.name_counter` is global and never reset (parmatch.ml:1942).
    let mut counter = tctx.conv_name_counter;
    let result = lp(tctx, typed, &mut counter, top_loc.unwrap_or(LocIdx::none()));
    tctx.conv_name_counter = counter;
    result
}

/// `Pattern_printer.print_pattern` (compiler/common/pattern_printer.ml).
fn print_counter_example(arena: &ParseArena, typed: &Pattern) -> String {
    use crate::parser::ast::{PatternDesc as P, PatternRecordField};

    fn is_generated_optional_constructor(arena: &ParseArena, lid: LidentIdx) -> bool {
        match arena.get_longident(lid) {
            Longident::Lident(name) => arena.get_string(*name).starts_with("#$"),
            _ => false,
        }
    }

    enum FieldState {
        Normal,
        Missing,
        PresentNone,
    }

    fn classify(arena: &ParseArena, pat: &Pattern) -> FieldState {
        match &pat.pat_desc {
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.is_empty()
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "None" =>
            {
                FieldState::Missing
            }
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.len() == 1
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "Some" =>
            {
                match classify(arena, &args[0]) {
                    FieldState::Missing | FieldState::PresentNone => FieldState::PresentNone,
                    FieldState::Normal => FieldState::Normal,
                }
            }
            _ => FieldState::Normal,
        }
    }

    fn strip_synthetic_some<'p>(arena: &ParseArena, pat: &'p Pattern) -> &'p Pattern {
        match &pat.pat_desc {
            PatternDesc::Tpat_construct(lid, cstr, args)
                if args.len() == 1
                    && is_generated_optional_constructor(arena, lid.txt)
                    && cstr.cstr_name == "Some" =>
            {
                &args[0]
            }
            _ => pat,
        }
    }

    fn untype(arena: &ParseArena, pat: &Pattern) -> crate::parse_arena::PatIdx {
        let none = LocIdx::none();
        match &pat.pat_desc {
            PatternDesc::Tpat_or(p1, inner, r_o) => {
                if let PatternDesc::Tpat_or(p2, p3, r_i) = &inner.pat_desc {
                    // A | (B | C) prints as (A | B) | C.
                    let mut new_inner = pat.clone();
                    new_inner.pat_desc = PatternDesc::Tpat_or(p1.clone(), p2.clone(), r_i.clone());
                    let mut new_outer = pat.clone();
                    new_outer.pat_desc =
                        PatternDesc::Tpat_or(Box::new(new_inner), p3.clone(), r_o.clone());
                    return untype(arena, &new_outer);
                }
                let left = untype(arena, p1);
                let right = untype(arena, inner);
                push_parsed_pattern(arena, none, P::Ppat_or(left, right))
            }
            PatternDesc::Tpat_any | PatternDesc::Tpat_var(_, _) => {
                push_parsed_pattern(arena, none, P::Ppat_any)
            }
            PatternDesc::Tpat_constant(constant) => push_parsed_pattern(
                arena,
                none,
                P::Ppat_constant(Box::new(untype_constant(constant))),
            ),
            PatternDesc::Tpat_alias(inner, _, _) => untype(arena, inner),
            PatternDesc::Tpat_tuple(items) => {
                let items = items.iter().map(|item| untype(arena, item)).collect();
                push_parsed_pattern(arena, none, P::Ppat_tuple(Box::new(items)))
            }
            PatternDesc::Tpat_construct(cstr_lid, cstr, args) => {
                let lid = Located::new(arena.push_typecheck_lident(&cstr.cstr_name), cstr_lid.loc);
                let mut items: Vec<_> = args.iter().map(|arg| untype(arena, arg)).collect();
                let arg = match items.len() {
                    0 => None,
                    1 => items.pop(),
                    _ => Some(push_parsed_pattern(arena, none, P::Ppat_tuple(Box::new(items)))),
                };
                push_parsed_pattern(arena, none, P::Ppat_construct(lid, arg))
            }
            PatternDesc::Tpat_variant(label, arg, _) => {
                let arg = arg.as_deref().map(|arg| untype(arena, arg));
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_variant(Box::new((label.clone().into(), arg))),
                )
            }
            PatternDesc::Tpat_record(subpatterns, closed_flag, rest) => {
                let mut saw_optional_rewrite = false;
                let fields = subpatterns
                    .iter()
                    .map(|(_, lbl, p, opt)| {
                        let state = if lbl.lbl_optional {
                            classify(arena, p)
                        } else {
                            FieldState::Normal
                        };
                        let (opt, pat) = match state {
                            FieldState::Missing => {
                                saw_optional_rewrite = true;
                                let none_lid =
                                    Located::new(arena.push_typecheck_lident("None"), none);
                                (true, push_parsed_pattern(arena, none, P::Ppat_construct(none_lid, None)))
                            }
                            FieldState::PresentNone => {
                                saw_optional_rewrite = true;
                                (*opt, untype(arena, strip_synthetic_some(arena, p)))
                            }
                            FieldState::Normal => (*opt, untype(arena, p)),
                        };
                        PatternRecordField {
                            lid: Located::new(arena.push_typecheck_lident(&lbl.lbl_name), none),
                            pat,
                            opt,
                        }
                    })
                    .collect();
                let closed_flag = if saw_optional_rewrite {
                    crate::parser::ast::ClosedFlag::Closed
                } else {
                    *closed_flag
                };
                let rest = rest.as_ref().map(|rest| crate::parser::ast::RecordPatRest {
                    rest_loc: rest.rest_name.loc,
                    rest_name: Located::new(
                        arena.push_typecheck_string(rest.rest_name.txt.clone()),
                        rest.rest_name.loc,
                    ),
                    rest_type: None,
                });
                push_parsed_pattern(
                    arena,
                    none,
                    P::Ppat_record(Box::new((fields, closed_flag, rest))),
                )
            }
            PatternDesc::Tpat_array(items) => {
                let items = items.iter().map(|item| untype(arena, item)).collect();
                push_parsed_pattern(arena, none, P::Ppat_array(Box::new(items)))
            }
        }
    }

    let parsed = untype(arena, typed);
    let doc = crate::parser::printer::print_pattern(
        &crate::parser::printer::PrinterState::init(),
        arena.get_pat(parsed),
        &mut crate::parser::comment_table::CommentTable::new(),
        arena,
    );
    doc.to_string(80)
}

/// A match case for the Parmatch checks.
#[derive(Clone)]
struct ParmatchCase {
    lhs: Pattern,
    guarded: bool,
    /// `all_rhs_idents` of the guard.
    guard_idents: Option<std::collections::BTreeSet<Ident>>,
}

/// `check_partial ~lev ?partial_match_warning_hint env expected_ty loc cases`
/// (typecore.ml:1761-1770).
#[allow(clippy::too_many_arguments)]
fn parmatch_check_partial(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    level: i32,
    hint: Option<&str>,
    expected_ty: TypeExprRef,
    loc: LocIdx,
    cases: &[crate::types::parmatch::CaseRef<'_>],
) -> crate::types::typedtree::Partial {
    let oracle = TypecoreParmatchOracle {
        tctx,
        env,
        expected_ty,
        level,
        partial_explode: if cases.len() == 1 { 5 } else { 0 },
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle);
    match pm.check_partial(hint, loc, cases) {
        crate::types::parmatch::Partiality::Partial => crate::types::typedtree::Partial::Partial,
        crate::types::parmatch::Partiality::Total => crate::types::typedtree::Partial::Total,
    }
}

fn case_refs(cases: &[crate::types::typedtree::Case]) -> Vec<crate::types::parmatch::CaseRef<'_>> {
    cases
        .iter()
        .map(|case| crate::types::parmatch::CaseRef {
            lhs: &case.c_lhs,
            guarded: case.c_guard.is_some(),
        })
        .collect()
}

/// `check_unused ~lev env expected_ty cases` (typecore.ml:1772-1776).
fn parmatch_check_unused(
    tctx: &mut TypeCheckContext<'_>,
    env: &Env,
    level: i32,
    expected_ty: TypeExprRef,
    cases: &[crate::types::parmatch::CaseRef<'_>],
) {
    let oracle = TypecoreParmatchOracle {
        tctx,
        env,
        expected_ty,
        level,
        partial_explode: 0,
        none_type: None,
    };
    let mut pm = crate::types::parmatch::Parmatch::new(oracle);
    pm.check_unused(cases);
}
